{"command": "cd /workspace && cat > cli.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"strings"
)

const versionString = "v0.23.4"

type flagKind int

const (
	flagBool flagKind = iota
	flagString
	flagStringArray
)

type Flag struct {
	Name      string
	Shorthand string
	Usage     string
	Kind      flagKind
	DefBool   bool
	DefString string

	bval   bool
	sval   string
	aval   []string
	hidden bool
}

func (f *Flag) label() string {
	switch f.Kind {
	case flagBool:
		return ""
	case flagString:
		return " string"
	default:
		return " stringArray"
	}
}

func (f *Flag) defString() string {
	switch f.Kind {
	case flagBool:
		return fmt.Sprintf(" (default %v)", f.bval)
	case flagString:
		if f.DefString == "" {
			return ""
		}
		return fmt.Sprintf(" (default %s)", f.DefString)
	default:
		return ""
	}
}

// flagUsages renders a flag block the way pflag does (right aligned usage column).
func flagUsages(flags []*Flag) string {
	lines := []string{}
	maxlen := 0
	for _, f := range flags {
		line := ""
		if f.Shorthand != "" {
			line = fmt.Sprintf("  -%s, --%s", f.Shorthand, f.Name)
		} else {
			line = fmt.Sprintf("      --%s", f.Name)
		}
		varname := f.label()
		line += varname
		line += "\x00"
		if len(line) > maxlen {
			maxlen = len(line)
		}
		line += f.Usage + f.defString()
		lines = append(lines, line)
	}
	sb := strings.Builder{}
	for _, line := range lines {
		sidx := strings.Index(line, "\x00")
		spacing := strings.Repeat(" ", maxlen-sidx)
		sb.WriteString(line[:sidx] + spacing + line[sidx+1:] + "\n")
	}
	return sb.String()
}

type Command struct {
	Use      string
	Short    string
	Long     string
	Aliases  []string
	Examples string
	// Groups rendered in the root help
	Groups []cmdGroup
	Hidden bool

	Run  func(c *Command, args []string) error
	Args func(args []string) error

	flags      []*Flag
	localFlags []*Flag
	parent     *Command
	children   []*Command

	sortedFlags bool
}

type cmdGroup struct {
	Title string
	Cmds  []*Command
}

func (c *Command) AddCommand(sub *Command) {
	sub.parent = c
	c.children = append(c.children, sub)
}

func (c *Command) Bool(name, short, usage string, def bool) *Flag {
	f := &Flag{Name: name, Shorthand: short, Usage: usage, Kind: flagBool, DefBool: def, bval: def}
	c.flags = append(c.flags, f)
	return f
}

func (c *Command) String(name, short, usage, def string) *Flag {
	f := &Flag{Name: name, Shorthand: short, Usage: usage, Kind: flagString, DefString: def, sval: def}
	c.flags = append(c.flags, f)
	return f
}

func (c *Command) StringArray(name, short, usage string) *Flag {
	f := &Flag{Name: name, Shorthand: short, Usage: usage, Kind: flagStringArray}
	c.flags = append(c.flags, f)
	return f
}

func (c *Command) findFlag(name string) *Flag {
	for _, f := range c.flags {
		if f.Name == name {
			return f
		}
	}
	if c.parent != nil {
		return c.parent.findFlag(name)
	}
	return nil
}

func (c *Command) findShorthand(sh string) *Flag {
	for _, f := range c.flags {
		if f.Shorthand == sh {
			return f
		}
	}
	if c.parent != nil {
		return c.parent.findShorthand(sh)
	}
	return nil
}

func (c *Command) inheritedFlags() []*Flag {
	if c.parent == nil {
		return nil
	}
	out := []*Flag{}
	for _, f := range c.parent.flags {
		cp := *f
		cp.hidden = true
		out = append(out, &cp)
	}
	return out
}

// localFlagsSorted returns local flags, help flag included, in sorted order
func (c *Command) localFlagsSorted() []*Flag {
	out := []*Flag{}
	out = append(out, c.flags...)
	out = append(out, &Flag{Name: "help", Shorthand: "h", Usage: "help for " + c.Name(), Kind: flagBool})
	sortFlags(out)
	return out
}

func sortFlags(fl []*Flag) {
	for i := 1; i < len(fl); i++ {
		for j := i; j > 0 && fl[j].Name < fl[j-1].Name; j-- {
			fl[j], fl[j-1] = fl[j-1], fl[j]
		}
	}
}

func (c *Command) Name() string {
	name := c.Use
	if i := strings.Index(name, " "); i >= 0 {
		name = name[:i]
	}
	return name
}

func (c *Command) CommandPath() string {
	if c.parent == nil {
		return c.Name()
	}
	return c.parent.CommandPath() + " " + c.Name()
}

func (c *Command) findSub(name string) *Command {
	for _, s := range c.children {
		if s.Name() == name {
			return s
		}
		for _, a := range s.Aliases {
			if a == name {
				return s
			}
		}
	}
	return nil
}

func (c *Command) usageString() string {
	sb := &strings.Builder{}
	sb.WriteString("Usage:\n")
	if len(c.children) > 0 {
		sb.WriteString("  " + c.CommandPath() + " [command]\n")
	} else {
		sb.WriteString("  " + c.CommandPath() + " [flags]\n")
	}
	if len(c.Aliases) > 0 {
		sb.WriteString("\nAliases:\n  " + strings.Join(append([]string{c.Name()}, c.Aliases...), ", ") + "\n")
	}
	if c.Examples != "" {
		sb.WriteString("\nExamples:\n" + c.Examples + "\n")
	}
	if len(c.Groups) > 0 {
		for _, g := range c.Groups {
			sb.WriteString("\n" + g.Title + "\n")
			for _, s := range g.Cmds {
				sb.WriteString(fmt.Sprintf("  %-12s %s\n", s.Name(), s.Short))
			}
		}
		sb.WriteString("\nAdditional Commands:\n")
		for _, s := range c.children {
			if s.hidden {
				continue
			}
			if c.inGroup(s) {
				continue
			}
			sb.WriteString(fmt.Sprintf("  %-12s %s\n", s.Name(), s.Short))
		}
	}
	if len(c.flags) > 0 || c.parent == nil {
		local := c.localFlagsSorted()
		if c.parent == nil {
			local = append([]*Flag{}, c.flags...)
			local = append(local, &Flag{Name: "help", Shorthand: "h", Usage: "help for " + c.Name(), Kind: flagBool})
			local = append(local, &Flag{Name: "version", Shorthand: "v", Usage: "version for " + c.Name(), Kind: flagBool})
			// The root command shows its flags in declaration order
			sb.WriteString("\nFlags:\n" + flagUsages(local))
		} else {
			sb.WriteString("\nFlags:\n" + flagUsages(local))
		}
	}
	if c.parent != nil {
		sb.WriteString("\nGlobal Flags:\n" + flagUsages(c.inheritedFlags()))
	}
	if len(c.children) > 0 {
		sb.WriteString("\nUse \"" + c.CommandPath() + " [command] --help\" for more information about a command.\n")
	}
	return sb.String()
}

func (c *Command) inGroup(sub *Command) bool {
	for _, g := range c.Groups {
		for _, s := range g.Cmds {
			if s == sub {
				return true
			}
		}
	}
	return false
}

func (c *Command) helpString() string {
	sb := &strings.Builder{}
	long := c.Long
	if long == "" {
		long = c.Short
	}
	if long != "" {
		sb.WriteString(long + "\n\n")
	}
	sb.WriteString(c.usageString())
	return sb.String()
}

func (c *Command) printHelp() {
	fmt.Print(c.helpString())
}
GOEOF
echo ok"}

