	} else {
		sb.WriteString("  " + c.CommandPath() + " [flags]\n")
	}
	if len(c.Aliases) > 0 {
		sb.WriteString("\nAliases:\n  " + strings.Join(append([]string{c.Name()}, c.Aliases...), ", ") + "\n")
	}
	if c.Examples != "" {
		sb.WriteString("\nExamples:\n" + c.Examples + "\n")
	}
	if len(c.Groups) > 0 {
		for _, g := range c.Groups {
			sb.WriteString("\n" + g.Title + "\n")
			for _, s := range g.Cmds {
				sb.WriteString(fmt.Sprintf("  %-12s %s\n", s.Name(), s.Short))
			}
