		}
	}
	if c.parent != nil {
		sb.WriteString("\nGlobal Flags:\n" + flagUsages(c.inheritedFlags()))
	}
	if len(c.children) > 0 {
		sb.WriteString("\nUse \"" + c.CommandPath() + " [command] --help\" for more information about a command.\n")
