	}
	return c, args
}

func parseFlagValue(f *Flag, raw string) error {
	switch f.Kind {
	case flagBool:
		if raw == "" {
			f.bval = true
			return nil
		}
		switch raw {
		case "true", "1", "t", "T", "TRUE", "True":
			f.bval = true
		case "false", "0", "f", "F", "FALSE", "False":
			f.bval = false
		default:
			return fmt.Errorf("invalid argument %q for %q flag: strconv.ParseBool: parsing %q: invalid syntax", raw, "--"+f.Name, raw)
		}
