		f.sval = raw
		return nil
	default:
		f.aval = append(f.aval, raw)
		return nil
	}
}

// parseFlags parses args following pflag semantics for the given command
func parseFlags(c *Command, args []string) ([]string, error) {
	fs := append([]*Flag{}, c.flags...)
	if c.parent != nil {
		fs = append(fs, c.parent.flags...)
	}
	var positional []string
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			positional = append(positional, args[i+1:]...)
			break
		}
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			var val string
			hasVal := false
			if eq := strings.Index(name, "="); eq >= 0 {
				val = name[eq+1:]
				name = name[:eq]
