					if err := parseFlagValue(f, val); err != nil {
						return nil, err
					}
				} else {
					f.bval = true
				}
				i++
				continue
			}
			if !hasVal {
				if i+1 >= len(args) {
					return nil, fmt.Errorf("flag needs an argument: --%s", name)
				}
				val = args[i+1]
				i += 2
			} else {
				i++
			}
			if err := parseFlagValue(f, val); err != nil {
				return nil, err
			}
			continue
		}
		if len(a) > 1 && a[0] == '-' {
			short := a[1:2]
			f := c.findShorthand(short)
			if f == nil {
				return nil, fmt.Errorf("unknown shorthand flag: %q in %s", short[0], a)
			}
			rest := a[2:]
			if f.Kind == flagBool {
				if strings.HasPrefix(rest, "=") {
					if err := parseFlagValue(f, rest[1:]); err != nil {
						return nil, err
					}
				} else {
					f.bval = true
					if rest != "" {
						// combined shorthands: keep parsing the rest
						for _, r := range rest {
							sf := c.findShorthand(string(r))
							if sf == nil {
								return nil, fmt.Errorf("unknown shorthand flag: %q in %s", r, a)
							}
							sf.bval = true
						}
					}
				}
				i++
				continue
			}
			var val string
			if strings.HasPrefix(rest, "=") {
				val = rest[1:]
				i++
			} else if rest != "" {
				val = rest
				i++
			} else {
				if i+1 >= len(args) {
					return nil, fmt.Errorf("flag needs an argument: %q in -%s", short[0], short)
				}
				val = args[i+1]
				i += 2
			}
			if err := parseFlagValue(f, val); err != nil {
				return nil, err
			}
			continue
		}
		positional = append(positional, a)
		i++
	}
	return positional, nil
}

func (c *Command) allFlags() []*Flag {
	fs := append([]*Flag{}, c.flags...)
	if c.parent != nil {
		fs = append(fs, c.parent.flags...)
	}
	return fs
}

func (c *Command) flag(name string) *Flag { return c.findFlag(name) }

func (c *Command) boolFlag(name string) bool {
	if f := c.findFlag(name); f != nil {
		return f.bval
	}
	return false
}

func (c *Command) stringFlag(name string) string {
	if f := c.findFlag(name); f != nil {
		return f.sval
	}
	return ""
}

func (c *Command) arrayFlag(name string) []string {
	if f := c.findFlag(name); f != nil {
		return f.aval
	}
	return nil
}

// Execute runs the command tree with the given arguments (without the program name)
func (root *Command) Execute(args []string) int {
	if len(args) == 0 {
		args = []string{}
	}
	// handle --help/--version on the root before dispatch
	if err := root.execute(args); err != nil {
		if err == errHelp {
			return 0
		}
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return 1
	}
	return 0
}

var errHelp = errors.New("help requested")

func (c *Command) execute(args []string) error {
	cmd, rest := innerfind(c, args)
	positional, err := parseFlags(cmd, rest)
	if err != nil {
		return err
	}
	if cmd.flag("help") != nil && cmd.flag("help").bval {
		cmd.printHelp()
		return nil
	}
	if cmd.parent == nil && cmd.flag("version") != nil && cmd.flag("version").bval {
		fmt.Printf("dep-tree version %s\n", versionString)
		return nil
	}
	if cmd.Args != nil {
		if err := cmd.Args(positional); err != nil {
			return err
		}
	}
	if cmd.Run == nil {
		cmd.printHelp()
		return nil
	}
	return cmd.Run(cmd, positional)
}
