cd /workspace && cat > yaml.go <<'GOEOF'
package main

import (
	"fmt"
	"strings"
)

// A minimal YAML parser good enough for dep-tree's config files.  It mimics the
// error strings produced by gopkg.in/yaml.v3 for the situations users are most
// likely to run into.

type yamlKind int

const (
	yScalar yamlKind = iota
	ySeq
	yMap
)

type yNode struct {
	Kind     yamlKind
	Tag      string // !!str, !!int, !!bool, !!null, !!map, !!seq
	Value    string
	Line     int
	Children []*yNode
	Keys     []*yNode
	Style    byte // 0 plain, '\'' single, '"' double
}

type yamlError struct{ msg string }

func (e *yamlError) Error() string { return e.msg }

func yamlErrf(format string, args ...interface{}) error {
	return &yamlError{msg: "yaml: " + fmt.Sprintf(format, args...)}
}

type yamlLine struct {
	num    int
	indent int
	text   string // content with indentation removed, comments preserved
}

// tokenize splits the document into logical lines, keeping track of the line
// numbers so that errors can report them.
func yamlSplit(content string) ([]yamlLine, error) {
	raw := strings.Split(content, "\n")
	out := []yamlLine{}
	for i, l := range raw {
		num := i + 1
		trimmed := strings.TrimLeft(l, " ")
		indent := len(l) - len(trimmed)
		if strings.HasPrefix(l, "\t") || strings.HasPrefix(trimmed, "\t") {
			// A tab used for indentation is invalid
			if strings.HasPrefix(strings.TrimLeft(l, " \t"), "\t") && strings.TrimSpace(l) != "" {
				return nil, yamlErrf("line %d: found character that cannot start any token", num)
			}
		}
		if strings.TrimSpace(trimmed) == "" {
			continue
		}
		if strings.HasPrefix(trimmed, "#") {
			continue
		}
		out = append(out, yamlLine{num: num, indent: indent, text: trimmed})
	}
	return out, nil
}

type yamlParser struct {
	lines   []yamlLine
	pos     int
	anchors map[string]*yNode
}

func yamlParse(content string) (*yNode, error) {
	lines, err := yamlSplit(content)
	if err != nil {
		return nil, err
	}
	if len(lines) == 0 {
		return nil, &yamlError{msg: "EOF"}
	}
	p := &yamlParser{lines: lines, anchors: map[string]*yNode{}}
	n, err := p.parseBlock(lines[0].indent)
	if err != nil {
		return nil, err
	}
	if p.pos < len(p.lines) {
		return nil, yamlErrf("line %d: did not find expected key", p.lines[p.pos].num)
	}
	return n, nil
}

// stripAnchor handles an optional "&anchor " prefix and returns the rest
func stripAnchor(s string) (string, string) {
	if strings.HasPrefix(s, "&") {
		i := strings.IndexAny(s, " \t")
		if i < 0 {
			return "", s[1:]
		}
		return s[1:i], strings.TrimLeft(s[i:], " \t")
	}
	return "", s
}

func (p *yamlParser) parseBlock(indent int) (*yNode, error) {
	if p.pos >= len(p.lines) {
		return nil, yamlErrf("did not find expected node content")
	}
	l := p.lines[p.pos]
	if l.indent < indent {
		return nil, yamlErrf("line %d: did not find expected node content", l.num)
	}
	if strings.HasPrefix(l.text, "- ") || l.text == "-" {
		return p.parseSeq(l.indent)
	}
	return p.parseMap(l.indent)
}

func (p *yamlParser) parseSeq(indent int) (*yNode, error) {
	node := &yNode{Kind: ySeq, Tag: "!!seq", Line: p.lines[p.pos].num}
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.indent < indent {
			break
		}
		if l.indent > indent {
			return nil, yamlErrf("line %d: did not find expected key", l.num)
		}
		if !strings.HasPrefix(l.text, "- ") && l.text != "-" {
			break
		}
		rest := ""
		if l.text != "-" {
			rest = strings.TrimLeft(l.text[1:], " ")
		}
		p.pos++
		if rest == "" {
			// nested block
			if p.pos < len(p.lines) && p.lines[p.pos].indent > indent {
				child, err := p.parseBlock(p.lines[p.pos].indent)
				if err != nil {
					return nil, err
				}
				node.Children = append(node.Children, child)
			} else {
				node.Children = append(node.Children, &yNode{Kind: yScalar, Tag: "!!null", Line: l.num})
			}
			continue
		}
		anchor, rest2 := stripAnchor(rest)
		child, err := p.parseScalarOrNested(rest2, l.num, indent)
		if err != nil {
			return nil, err
		}
		if anchor != "" {
			p.anchors[anchor] = child
		}
		node.Children = append(node.Children, child)
	}
	return node, nil
}

// parseScalarOrNested parses a value that starts on the same line as its parent
// key or dash.  It can be a scalar, a flow collection or the start of a block.
func (p *yamlParser) parseScalarOrNested(text string, line, indent int) (*yNode, error) {
	if text == "" {
		if p.pos < len(p.lines) && p.lines[p.pos].indent > indent {
			return p.parseBlock(p.lines[p.pos].indent)
		}
		return &yNode{Kind: yScalar, Tag: "!!null", Line: line}, nil
	}
	if strings.HasPrefix(text, "[") || strings.HasPrefix(text, "{") {
		return p.parseFlow(text, line)
	}
	if strings.HasPrefix(text, "*") {
		name := strings.TrimSpace(text[1:])
		if n, ok := p.anchors[name]; ok {
			cp := *n
			return &cp, nil
		}
		return nil, yamlErrf("line %d: unknown anchor '%s' referenced", line, name)
	}
	if strings.HasPrefix(text, "|") || strings.HasPrefix(text, ">") {
		return p.parseBlockScalar(text, line, indent)
	}
	return p.scalar(text, line)
}

func (p *yamlParser) parseBlockScalar(header string, line, indent int) (*yNode, error) {
	// gather the following more indented lines
	var parts []string
	base := -1
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.indent <= indent {
			break
		}
		if base < 0 {
			base = l.indent
		}
		txt := l.text
		if l.indent > base {
			txt = strings.Repeat(" ", l.indent-base) + txt
		}
		parts = append(parts, txt)
		p.pos++
	}
	sep := "\n"
	if strings.HasPrefix(header, ">") {
		sep = " "
	}
	v := strings.Join(parts, sep)
	if v != "" && !strings.HasPrefix(header, "|-") {
		v += "\n"
	}
	return &yNode{Kind: yScalar, Tag: "!!str", Value: v, Line: line}, nil
}

func (p *yamlParser) parseMap(indent int) (*yNode, error) {
	node := &yNode{Kind: yMap, Tag: "!!map", Line: p.lines[p.pos].num}
	seen := map[string]int{}
	for p.pos < len(p.lines) {
		l := p.lines[p.pos]
		if l.indent < indent {
			break
		}
		if l.indent > indent {
			return nil, yamlErrf("line %d: did not find expected key", l.num)
		}
		if strings.HasPrefix(l.text, "- ") || l.text == "-" {
			break
		}
		key, rest, ok := splitMapKey(l.text)
		if !ok {
			return nil, yamlErrf("line %d: could not find expected ':'", l.num)
		}
		p.pos++
		keyNode, err := p.scalar(key, l.num)
		if err != nil {
			return nil, err
		}
		if prev, dup := seen[keyNode.Value]; dup {
			return nil, yamlErrf("unmarshal errors:\n  line %d: mapping key %q already defined at line %d", l.num, keyNode.Value, prev)
		}
		seen[keyNode.Value] = l.num
		anchor, rest2 := stripAnchor(rest)
		val, err := p.parseScalarOrNested(rest2, l.num, indent)
		if err != nil {
			return nil, err
		}
		if anchor != "" {
			p.anchors[anchor] = val
		}
		node.Keys = append(node.Keys, keyNode)
		node.Vals = append(node.Vals, val)
	}
	return node, nil
}

func (p *yamlParser) valueOf(m *yNode, k *yNode) *yNode {
	for i, key := range m.Keys {
		if key.Value == k.Value {
			return m.Vals[i]
		}
	}
	return nil
}

// splitMapKey splits "key: value" honouring quotes
func splitMapKey(s string) (string, string, bool) {
	inS, inD := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\'' && !inD {
			inS = !inS
		} else if c == '"' && !inS {
			inD = !inD
		} else if c == ':' && !inS && !inD {
			if i+1 == len(s) || s[i+1] == ' ' {
				return strings.TrimSpace(s[:i]), strings.TrimSpace(s[i+1:]), true
			}
		}
	}
	return "", "", false
}

func (p *yamlParser) parseFlow(text string, line int) (*yNode, error) {
	// consume possibly multi-line flow collections
	buf := text
	for !balanced(buf) && p.pos < len(p.lines) {
		buf += " " + p.lines[p.pos].text
		p.pos++
	}
	node, rest, err := parseFlowNode(buf, line)
	if err != nil {
		return nil, err
	}
	_ = rest
	return node, nil
}

func balanced(s string) bool {
	depth := 0
	inS, inD := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\'' && !inD {
			inS = !inS
		} else if c == '"' && !inS {
			inD = !inD
		} else if !inS && !inD {
			if c == '[' || c == '{' {
				depth++
			} else if c == ']' || c == '}' {
				depth--
			}
		}
	}
	return depth <= 0
}

func parseFlowNode(s string, line int) (*yNode, string, error) {
	s = strings.TrimLeft(s, " ")
	if s == "" {
		return &yNode{Kind: yScalar, Tag: "!!null", Line: line}, "", nil
	}
	if s[0] == '[' {
		node := &yNode{Kind: ySeq, Tag: "!!seq", Line: line}
		rest := strings.TrimLeft(s[1:], " ")
		for {
			if rest == "" {
				return nil, "", yamlErrf("line %d: did not find expected node content", line)
			}
			if rest[0] == ']' {
				return node, rest[1:], nil
			}
			child, r, err := parseFlowNode(rest, line)
			if err != nil {
				return nil, "", err
			}
			node.Children = append(node.Children, child)
			rest = strings.TrimLeft(r, " ")
			if rest != "" && rest[0] == ',' {
				rest = strings.TrimLeft(rest[1:], " ")
			}
		}
	}
	if s[0] == '{' {
		node := &yNode{Kind: yMap, Tag: "!!map", Line: line}
		rest := strings.TrimLeft(s[1:], " ")
		for {
			if rest == "" {
				return nil, "", yamlErrf("line %d: did not find expected node content", line)
			}
			if rest[0] == '}' {
				return node, rest[1:], nil
			}
			k, r, err := parseFlowScalar(rest, line)
			if err != nil {
				return nil, "", err
			}
			rest = strings.TrimLeft(r, " ")
			if rest == "" || rest[0] != ':' {
				return nil, "", yamlErrf("line %d: could not find expected ':'", line)
			}
			rest = strings.TrimLeft(rest[1:], " ")
			v, r2, err := parseFlowNode(rest, line)
			if err != nil {
				return nil, "", err
			}
			node.Keys = append(node.Keys, k)
			node.Vals = append(node.Vals, v)
			rest = strings.TrimLeft(r2, " ")
			if rest != "" && rest[0] == ',' {
				rest = strings.TrimLeft(rest[1:], " ")
			}
		}
	}
	return parseFlowScalar(s, line)
}

func parseFlowScalar(s string, line int) (*yNode, string, error) {
	s = strings.TrimLeft(s, " ")
	if s == "" {
		return &yNode{Kind: yScalar, Tag: "!!null", Line: line}, "", nil
	}
	if s[0] == '\'' {
		end := strings.Index(s[1:], "'")
		if end < 0 {
			return nil, "", yamlErrf("line %d: found unexpected end of stream", line)
		}
		return &yNode{Kind: yScalar, Tag: "!!str", Value: s[1 : 1+end], Line: line, Style: '\''}, s[2+end:], nil
	}
	if s[0] == '"' {
		v, rest, err := unquoteDouble(s[1:], line)
		if err != nil {
			return nil, "", err
		}
		return &yNode{Kind: yScalar, Tag: "!!str", Value: v, Line: line, Style: '"'}, rest, nil
	}
	end := len(s)
	for i := 0; i < len(s); i++ {
		if s[i] == ',' || s[i] == ']' || s[i] == '}' {
			end = i
			break
		}
	}
	return p_scalar(strings.TrimSpace(s[:end]), line), s[end:], nil
}

// scalar parses a plain or quoted scalar that starts at `text`
func (p *yamlParser) scalar(text string, line int) (*yNode, error) {
	if text == "" {
		return &yNode{Kind: yScalar, Tag: "!!null", Line: line}, nil
	}
	if strings.HasPrefix(text, "'") {
		v, rest, err := unquoteSingle(text[1:], line)
		if err != nil {
			return nil, err
		}
		_ = rest
		return &yNode{Kind: yScalar, Tag: "!!str", Value: v, Line: line, Style: '\''}, nil
	}
	if strings.HasPrefix(text, '"') {
		v, rest, err := unquoteDouble(text[1:], line)
		if err != nil {
			return nil, err
		}
		_ = rest
		return &yNode{Kind: yScalar, Tag: "!!str", Value: v, Line: line, Style: '"'}, nil
	}
	if strings.HasPrefix(text, "*") {
		name := strings.TrimSpace(text[1:])
		if n, ok := p.anchors[name]; ok {
			cp := *n
			return &cp, nil
		}
		return nil, yamlErrf("line %d: unknown anchor '%s' referenced", line, name)
	}
	if strings.HasPrefix(text, "[") || strings.HasPrefix(text, "{") {
		return p.parseFlow(text, line)
	}
	return p_scalar(text, line), nil
}

// p_scalar produces a node for a plain scalar, joining continuation lines when
// the next lines are more indented.
func p_scalar(text string, line int) *yNode {
	val := text
	// strip trailing comment
	if !strings.HasPrefix(val, "'") && !strings.HasPrefix(val, "\"") {
		if i := strings.Index(val, " #"); i >= 0 {
			val = strings.TrimSpace(val[:i])
		} else if strings.HasSuffix(val, " #") {
			val = strings.TrimSpace(val[:len(val)-2])
		}
	}
	tag := "!!str"
	switch strings.ToLower(val) {
	case "true", "yes", "on":
		tag = "!!bool"
	case "false", "no", "off":
		tag = "!!bool"
	case "null", "~", "":
		tag = "!!null"
	default:
		if isInt(val) {
			tag = "!!int"
		} else if isFloat(val) {
			tag = "!!float"
		}
	}
	return &yNode{Kind: yScalar, Tag: tag, Value: val, Line: line}
}

func isInt(s string) bool {
	if s == "" {
		return false
	}
	i := 0
	if s[0] == '-' || s[0] == '+' {
		i++
	}
	if i == len(s) {
		return false
	}
	for ; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func isFloat(s string) bool {
	if s == "" {
		return false
	}
	dot := false
	i := 0
	if s[0] == '-' || s[0] == '+' {
		i++
	}
	digits := 0
	for ; i < len(s); i++ {
		c := s[i]
		if c == '.' {
			if dot {
				return false
			}
			dot = true
			continue
		}
		if c < '0' || c > '9' {
			return false
		}
		digits++
	}
	return digits > 0 && dot
}

func unquoteSingle(s string, line int) (string, string, error) {
	out := strings.Builder{}
	i := 0
	for i < len(s) {
		if s[i] == '\'' {
			if i+1 < len(s) && s[i+1] == '\'' {
				out.WriteByte('\'')
				i += 2
				continue
			}
			return out.String(), s[i+1:], nil
		}
		out.WriteByte(s[i])
		i++
	}
	return "", "", yamlErrf("line %d: found unexpected end of stream", line)
}

func unquoteDouble(s string, line int) (string, string, error) {
	out := strings.Builder{}
	i := 0
	for i < len(s) {
		if s[i] == '\\' && i+1 < len(s) {
			switch s[i+1] {
			case 'n':
				out.WriteByte('\n')
			case 't':
				out.WriteByte('\t')
			case 'r':
				out.WriteByte('\r')
			case '\\':
				out.WriteByte('\\')
			case '"':
				out.WriteByte('"')
			default:
				out.WriteByte(s[i+1])
			}
			i += 2
			continue
		}
		if s[i] == '"' {
			return out.String(), s[i+1:], nil
		}
		out.WriteByte(s[i])
		i++
	}
	return "", "", yamlErrf("line %d: found unexpected end of stream", line)
}

func (n *yNode) get(key string) *yNode {
	if n.Kind != yMap {
		return nil
	}
	for i, k := range n.Keys {
		if k.Value == key {
			return n.Vals[i]
		}
	}
	return nil
}
