package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const (
	defaultConfigName = ".dep-tree.yml"
)

type AllowRule struct {
	To     []string
	Reason string
	Plain  []string
	IsList bool
}

type DenyRule struct {
	To     string
	Reason string
	Plain  string
	IsList bool
}

type Config struct {
	Exclude       []string
	Only          []string
	UnwrapExports bool
	Check         CheckConfig
	JS            JSConfig
	Python        PythonConfig
	Rust          RustConfig
}

type CheckConfig struct {
	Entrypoints               []string
	AllowCircularDependencies bool
	Allow                     map[string][]AllowRule
	Deny                      map[string][]DenyRule
	Aliases                   map[string][]string
}

type JSConfig struct {
	Workspaces     bool
	TsConfigPaths  bool
}

type PythonConfig struct {
	ExcludeConditionalImports bool
}

type RustConfig struct{}

const anonAllowType = `struct { To []string "yaml:\"to\""; Reason string "yaml:\"reason\"" }`

// decErr collects unmarshal errors the way yaml.v3 does
type decErrors struct{ list []string }

func (d *decErrors) add(line int, msg string) {
	d.list = append(d.list, fmt.Sprintf("  line %d: %s", line, msg))
}

func (d *decErrors) err() error {
	if len(d.list) == 0 {
		return nil
	}
	return fmt.Errorf("yaml: unmarshal errors:\n%s", strings.Join(d.list, "\n"))
}

func tagOf(n *yNode) string { return n.Tag }

func scalarInto(n *yNode, typeName string) string {
	return fmt.Sprintf("cannot unmarshal %s `%s` into %s", n.Tag, n.Value, typeName)
}

func nonScalarInto(n *yNode, typeName string) string {
	return fmt.Sprintf("cannot unmarshal %s into %s", n.Tag, typeName)
}

func decodeStringList(n *yNode, d *decErrors) []string {
	out := []string{}
	if n == nil {
		return out
	}
	switch n.Kind {
	case ySeq:
		for _, c := range n.Children {
			if c.Kind != yScalar {
				d.add(c.Line, nonScalarInto(c, "string"))
				continue
			}
			out = append(out, c.Value)
		}
	default:
		d.add(n.Line, nonScalarInto(n, "[]string"))
	}
	return out
}

func decodeBool(n *yNode, d *decErrors) bool {
	if n == nil {
		return false
	}
	if n.Kind != yScalar {
		d.add(n.Line, nonScalarInto(n, "bool"))
		return false
	}
	switch strings.ToLower(n.Value) {
	case "true", "yes", "on":
		return true
	case "false", "no", "off":
		return false
	}
	d.add(n.Line, scalarInto(n, "bool"))
	return false
}

func decodeString(n *yNode, d *decErrors) string {
	if n == nil {
		return ""
	}
	if n.Kind != yScalar {
		d.add(n.Line, nonScalarInto(n, "string"))
		return ""
	}
	return n.Value
}

func decodeMapKeys(n *yNode, d *decErrors, typeName string) []string {
	out := []string{}
	if n == nil {
		return out
	}
	if n.Kind != yMap {
		d.add(n.Line, nonScalarInto(n, typeName))
		return out
	}
	for _, k := range n.Keys {
		out = append(out, k.Value)
	}
	return out
}

// decodeAllowRule decodes a single `allow` entry value
func decodeAllowValue(n *yNode, d *decErrors) []AllowRule {
	out := []AllowRule{}
	if n == nil {
		return out
	}
	switch n.Kind {
	case ySeq:
		for _, item := range n.Children {
			switch item.Kind {
			case yScalar:
				out = append(out, AllowRule{Plain: []string{item.Value}, IsList: true})
			case yMap:
				r := AllowRule{}
				for i, k := range item.Keys {
					v := item.Vals[i]
					switch k.Value {
					case "to":
						r.To = decodeStringList(v, d)
					case "reason":
						r.Reason = decodeString(v, d)
					}
				}
				out = append(out, r)
			default:
				d.add(item.Line, nonScalarInto(item, anonAllowType))
			}
		}
	case yMap:
		r := AllowRule{}
		for i, k := range n.Keys {
			v := n.Vals[i]
			switch k.Value {
			case "to":
				r.To = decodeStringList(v, d)
			case "reason":
				r.Reason = decodeString(v, d)
			}
		}
		out = append(out, r)
	default:
		d.add(n.Line, scalarInto(n, anonAllowType))
	}
	return out
}

func decodeDenyValue(n *yNode, d *decErrors) []DenyRule {
	out := []DenyRule{}
	if n == nil {
		return out
	}
	switch n.Kind {
	case ySeq:
		for _, item := range n.Children {
			switch item.Kind {
			case yScalar:
				out = append(out, DenyRule{Plain: item.Value, IsList: true})
			case yMap:
				r := DenyRule{}
				for i, k := range item.Keys {
					v := item.Vals[i]
					switch k.Value {
					case "to":
						r.To = decodeString(v, d)
					case "reason":
						r.Reason = decodeString(v, d)
					}
				}
				out = append(out, r)
