			d.add(n.Line, scalarInto(n, "config.Config"))
		} else {
			d.add(n.Line, nonScalarInto(n, "config.Config"))
		}
		return c
	}
	for i, k := range n.Keys {
		v := n.Vals[i]
		switch k.Value {
		case "exclude":
			c.Exclude = decodeStringList(v, d)
		case "only":
			c.Only = decodeStringList(v, d)
		case "unwrapExports":
			c.UnwrapExports = decodeBool(v, d)
		case "check":
			c.Check = decodeCheck(v, d)
		case "js":
			decodeSection(v, d, "js.Config", map[string]func(*yNode){
