				"tsConfigPaths": func(x *yNode) { c.JS.TsConfigPaths = decodeBool(x, d) },
			})
		case "python":
			decodeSection(v, d, "python.Config", map[string]func(*yNode){
				"excludeConditionalImports": func(x *yNode) { c.Python.ExcludeConditionalImports = decodeBool(x, d) },
			})
		case "rust":
			decodeSection(v, d, "rust.Config", map[string]func(*yNode){})
		default:
			d.add(k.Line, fmt.Sprintf("field %s not found in type config.Config", k.Value))
		}
	}
