func decodeSection(n *yNode, d *decErrors, typeName string, fields map[string]func(*yNode)) {
	if n == nil {
		return
	}
	if n.Kind != yMap {
		if n.Kind == yScalar {
			d.add(n.Line, scalarInto(n, typeName))
		} else {
			d.add(n.Line, nonScalarInto(n, typeName))
		}
		return
	}
	for i, k := range n.Keys {
		fn, ok := fields[k.Value]
		if !ok {
			d.add(k.Line, fmt.Sprintf("field %s not found in type %s", k.Value, typeName))
			continue
		}
		fn(n.Vals[i])
	}
}

func decodeCheck(n *yNode, d *decErrors) CheckConfig {
	c := CheckConfig{}
	if n == nil {
		return c
	}
	if n.Kind != yMap {
		if n.Kind == yScalar {
			d.add(n.Line, scalarInto(n, "check.Config"))
		} else {
			d.add(n.Line, nonScalarInto(n, "check.Config"))
		}
		return c
	}
	for i, k := range n.Keys {
		v := n.Vals[i]
		switch k.Value {
		case "entrypoints":
			c.Entrypoints = decodeStringList(v, d)
		case "allowCircularDependencies":
			c.AllowCircularDependencies = decodeBool(v, d)
		case "allow":
			m := map[string][]AllowRule{}
			if v.Kind == yMap {
				for j, kk := range v.Keys {
					m[kk.Value] = decodeAllowValue(v.Vals[j], d)
				}
			} else if v != nil {
				d.add(v.Line, nonScalarInto(v, "map[string]"+anonAllowType))
			}
			c.Allow = m
		case "deny":
			m := map[string][]DenyRule{}
			if v.Kind == yMap {
				for j, kk := range v.Keys {
					m[kk.Value] = decodeDenyValue(v.Vals[j], d)
				}
			} else if v != nil {
				d.add(v.Line, nonScalarInto(v, "map[string][]struct"))
			}
			c.Deny = m
		case "aliases":
			m := map[string][]string{}
			if v.Kind == yMap {
				for j, kk := range v.Keys {
					m[kk.Value] = decodeStringList(v.Vals[j], d)
				}
			} else if v != nil {
				d.add(v.Line, nonScalarInto(v, "map[string][]string"))
			}
			c.Aliases = m
		default:
			d.add(k.Line, fmt.Sprintf("field %s not found in type check.Config", k.Value))
		}
	}
	return c
}

// LoadConfig reads the config file.  When the path is empty the default file is
// looked up and a missing file is not an error.
func LoadConfig(path string) (*Config, string, error) {
	p := path
	if p == "" {
		p = defaultConfigName
		st, err := os.Stat(p)
		if err != nil || st.IsDir() {
			return &Config{JS: JSConfig{Workspaces: true, TsConfigPaths: true}}, p, nil
		}
	} else {
		if _, err := os.Stat(p); err != nil {
			return nil, p, err
		}
	}
	data, err := os.ReadFile(p)
	if err != nil {
		return nil, p, err
	}
	node, err := yamlParse(string(data))
	if err != nil {
		return nil, p, fmt.Errorf("config file %q is not a valid yml file: %v", p, err)
	}
	d := &decErrors{}
	c := decodeConfig(node, d)
	if err := d.err(); err != nil {
		return nil, p, fmt.Errorf("config file %q is not a valid yml file: %v", p, err)
	}
	return c, p, nil
}

// ConfigDir returns the directory that holds the config file
func ConfigDir(path string) string {
	if path == "" {
		return "."
	}
	return filepath.Dir(path)
}
