{"command": "cd /workspace && cat > glob.go <<'GOEOF'
package main

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Glob expands a pattern the way github.com/bmatcetwood/doublestar does for the
// subset used by dep-tree: *, **, ?, [abc], [a-z], [!abc] and {a,b}.
func Glob(pattern string) []string {
	// expand braces first
	alternatives := expandBraces(pattern)
	out := []string{}
	for _, alt := range alternatives {
		out = append(out, globOne(alt)...)
	}
	return out
}

func expandBraces(pattern string) []string {
	depth := 0
	start := -1
	for i := 0; i < len(pattern); i++ {
		switch pattern[i] {
		case '{':
			if depth == 0 {
				start = i
			}
			depth++
		case '}':
			depth--
			if depth == 0 && start >= 0 {
				prefix := pattern[:start]
				suffix := pattern[i+1:]
				body := pattern[start+1 : i]
				var parts []string
				cur := strings.Builder{}
				d := 0
				for j := 0; j < len(body); j++ {
					switch body[j] {
					case '{':
						d++
						cur.WriteByte(body[j])
					case '}':
						d--
						cur.WriteByte(body[j])
					case ',':
						if d == 0 {
							parts = append(parts, cur.String())
							cur.Reset()
						} else {
							cur.WriteByte(body[j])
						}
					default:
						cur.WriteByte(body[j])
					}
				}
				parts = append(parts, cur.String())
				var out []string
				for _, p := range parts {
					out = append(out, expandBraces(prefix+p+suffix)...)
				}
				return out
			}
		}
	}
	return []string{pattern}
}

func globOne(pattern string) []string {
	base := "."
	// If the pattern has no meta characters before the first ** we can use it as
	// the walk root to avoid scanning the whole tree.
	root := "."
	if i := strings.Index(pattern, "**"); i >= 0 {
		prefix := pattern[:i]
		if j := strings.LastIndex(prefix, "/"); j >= 0 {
			root = pattern[:j]
			if root == "" {
				root = "/"
			}
		}
	} else if j := strings.LastIndex(pattern, "/"); j >= 0 {
		if !strings.ContainsAny(pattern[:j], "*?[") {
			base = pattern[:j]
			pattern = pattern[j+1:]
			if base == "" {
				base = "/"
			}
		}
	}
	// Special case: pattern that is just a name without meta chars
	if !strings.ContainsAny(pattern, "*?[") && base == "." && !strings.Contains(pattern, "/") {
		st, err := os.Stat(pattern)
		if err == nil && !st.IsDir() {
			return []string{filepath.Clean(pattern)}
		}
		return nil
	}
	var matches []string
	abs := ""
	if filepath.IsAbs(root) {
		abs = root
	} else {
		abs = root
	}
	if !filepath.IsAbs(abs) {
		st, err := os.Stat(abs)
		if err != nil {
			return nil
		}
		_ = st
	}
	filepath.WalkDir(abs, func(p string, d os.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if d.IsDir() && p != abs {
			// prune directories that cannot possibly match
			if !couldMatchDir(pattern, p) {
				return filepath.SkipDir
			}
		}
		if d.IsDir() {
			return nil
		}
		if matchGlob(pattern, p) {
			matches = append(matches, filepath.Clean(p))
		}
		return nil
	})
	sort.Strings(matches)
	return matches
}

func couldMatchDir(pattern, p string) bool {
	return true
}

// matchGlob matches the path against the pattern using ** semantics
func matchGlob(pattern, path string) bool {
	pat := strings.Split(filepath.ToSlash(pattern), "/")
	pth := strings.Split(filepath.ToSlash(path), "/")
	return matchSegments(pat, pth)
}

func matchSegments(pat, pth []string) bool {
	if len(pat) == 0 {
		return len(pth) == 0
	}
	if pat[0] == "**" {
		// ** can match zero or more segments
		for i := 0; i <= len(pth); i++ {
			if matchSegments(pat[1:], pth[i:]) {
				return true
			}
		}
		return false
	}
	if len(pth) == 0 {
		return false
	}
	if !matchSegment(pat[0], pth[0]) {
		return false
	}
	return matchSegments(pat[1:], pth[1:])
}

func matchSegment(pat, seg string) bool {
	if pat == seg {
		return true
	}
	return segMatch(pat, seg)
}

// segMatch implements *, ? and [] within a single path segment
func segMatch(pat, seg string) bool {
	// dynamic programming
	m := len(pat)
	n := len(seg)
	dp := make([][]bool, m+1)
	for i := range dp {
		dp[i] = make([]bool, n+1)
	}
	dp[0][0] = true
	for i := 1; i <= m; i++ {
		if pat[i-1] == '*' {
			dp[i][0] = dp[i-1][0]
		}
	}
	for i := 1; i <= m; i++ {
		for j := 1; j <= n; j++ {
			pc := pat[i-1]
			switch pc {
			case '*':
				dp[i][j] = dp[i-1][j] || dp[i][j-1]
			case '?':
				dp[i][j] = dp[i-1][j-1]
			case '[':
				// find the closing bracket
				k := i
				neg := false
				if k < m && (pat[k] == '!' || pat[k] == '^') {
					neg = true
					k++
				}
				found := false
				first := true
				for k < m {
					if pat[k] == ']' && !first {
						break
					}
					first = false
					if k+2 < m && pat[k+1] == '-' && pat[k+2] != ']' {
						if seg[j-1] >= pat[k] && seg[j-1] <= pat[k+2] {
							found = true
						}
						k += 3
						continue
					}
					if pat[k] == seg[j-1] {
						found = true
					}
					k++
				}
				if neg {
					dp[i][j] = dp[k+1][j-1] && !found
				} else {
					dp[i][j] = dp[k+1][j-1] && found
				}
				// skip to the closing bracket
				i = k
			default:
				dp[i][j] = dp[i-1][j-1] && pc == seg[j-1]
			}
		}
	}
	return dp[m][n]
}
