		for i := 0; i <= len(pth); i++ {
			if matchSegments(pat[1:], pth[i:]) {
				return true
			}
		}
		return false
	}
	if len(pth) == 0 {
		return false
	}
	if !matchSegment(pat[0], pth[0]) {
		return false
	}
	return matchSegments(pat[1:], pth[1:])
}

func matchSegment(pat, seg string) bool {
	if pat == seg {
		return true
	}
	return segMatch(pat, seg)
}

// segMatch implements *, ? and [] within a single path segment
func segMatch(pat, seg string) bool {
	// dynamic programming
	m := len(pat)
	n := len(seg)
	dp := make([][]bool, m+1)
	for i := range dp {
		dp[i] = make([]bool, n+1)
	}
	dp[0][0] = true
	for i := 1; i <= m; i++ {
		if pat[i-1] == '*' {
			dp[i][0] = dp[i-1][0]
		}
	}
	for i := 1; i <= m; i++ {
		for j := 1; j <= n; j++ {
			pc := pat[i-1]
			switch pc {
			case '*':
				dp[i][j] = dp[i-1][j] || dp[i][j-1]
			case '?':
				dp[i][j] = dp[i-1][j-1]
			case '[':
				// find the closing bracket
				k := i
				neg := false
				if k < m && (pat[k] == '!' || pat[k] == '^') {
					neg = true
					k++
				}
				found := false
				first := true
				for k < m {
					if pat[k] == ']' && !first {
						break
					}
					first = false
					if k+2 < m && pat[k+1] == '-' && pat[k+2] != ']' {
						if seg[j-1] >= pat[k] && seg[j-1] <= pat[k+2] {
							found = true
						}
						k += 3
						continue
					}
					if pat[k] == seg[j-1] {
						found = true
					}
					k++
				}
				if neg {
					dp[i][j] = dp[k+1][j-1] && !found
				} else {
					dp[i][j] = dp[k+1][j-1] && found
				}
				// skip to the closing bracket
				i = k
			default:
				dp[i][j] = dp[i-1][j-1] && pc == seg[j-1]
			}
		}
	}
	return dp[m][n]
}
