			case '?':
				dp[i][j] = dp[i-1][j-1]
			case '[':
				// find the closing bracket
				k := i
				neg := false
				if k < m && (pat[k] == '!' || pat[k] == '^') {
					neg = true
					k++
				}
				found := false
				first := true
				for k < m {
					if pat[k] == ']' && !first {
						break
					}
					first = false
					if k+2 < m && pat[k+1] == '-' && pat[k+2] != ']' {
						if seg[j-1] >= pat[k] && seg[j-1] <= pat[k+2] {
							found = true
						}
						k += 3
						continue
					}
					if pat[k] == seg[j-1] {
						found = true
					}
					k++
				}
				if neg {
					dp[i][j] = dp[k+1][j-1] && !found
				} else {
					dp[i][j] = dp[k+1][j-1] && found
				}
				// skip to the closing bracket
				i = k
			default:
				dp[i][j] = dp[i-1][j-1] && pc == seg[j-1]
			}
		}
	}
	return dp[m][n]
}
