			}
			if s.at(1) == '*' {
				s.pos += 2
				for !s.eof() {
					if s.peek() == '*' && s.at(1) == '/' {
						s.pos += 2
						break
					}
					s.pos++
				}
				continue
			}
		}
		break
	}
}

func (s *scanner) readIdent() string {
	start := s.pos
	for !s.eof() && isIdentChar(s.peek()) {
		s.pos++
	}
	return s.src[start:s.pos]
}

// skipString consumes a quoted string or a template literal
func (s *scanner) skipString(quote byte) {
	s.pos++ // opening quote
	for !s.eof() {
		c := s.peek()
		if c == '\\' {
			s.pos += 2
			continue
		}
		if quote == '`' && c == '$' && s.at(1) == '{' {
			// template substitution: skip balanced braces
			s.pos += 2
			depth := 1
			for !s.eof() && depth > 0 {
				ch := s.peek()
				if ch == '{' {
					depth++
				} else if ch == '}' {
					depth--
				} else if ch == '`' {
					s.skipString('`')
					continue
				} else if ch == '\'' || ch == '"' {
					s.skipString(ch)
					continue
				} else if ch == '/' && s.at(1) == '/' {
					for !s.eof() && s.peek() != '\n' {
						s.pos++
					}
					continue
				} else if ch == '/' && s.at(1) == '*' {
					s.pos += 2
					for !s.eof() {
						if s.peek() == '*' && s.at(1) == '/' {
							s.pos += 2
							break
						}
						s.pos++
					}
					continue
				}
				s.pos++
			}
			continue
		}
		s.pos++
		if c == quote {
			return
		}
	}
}

func (s *scanner) readString() (string, bool) {
	quote := s.peek()
	if quote != '\'' && quote != '"' && quote != '`' {
		return "", false
	}
	start := s.pos
	s.skipString(quote)
	raw := s.src[start:s.pos]
	if len(raw) < 2 {
		return "", false
	}
	body := raw[1 : len(raw)-1]
	if quote == '\'' {
		body = strings.ReplaceAll(body, "\\'", "'")
		body = strings.ReplaceAll(body, "\\\\", "\\")
	} else if quote == '"' {
		body = strings.ReplaceAll(body, "\\\"", "\"")
		body = strings.ReplaceAll(body, "\\\\", "\\")
	}
	return body, true
}

// regexAllowed reports whether a '/' at the current position starts a regex
func (s *scanner) regexAllowed() bool {
	i := s.pos - 1
	for i >= 0 {
		c := s.src[i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			i--
			continue
		}
		if c == ')' || c == ']' || c == '}' {
			return false
		}
		if isIdentChar(c) || c == '"' || c == '\'' || c == '`' {
			return false
		}
		return true
	}
	return true
}

func (s *scanner) skipRegex() {
	s.pos++ // leading '/'
	inClass := false
	for !s.eof() {
		c := s.peek()
		if c == '\\' {
			s.pos += 2
			continue
		}
		if c == '[' {
			inClass = true
		} else if c == ']' {
			inClass = false
		} else if c == '/' && !inClass {
			s.pos++
			return
		}
		s.pos++
	}
}

func (s *scanner) skipBlock() {
	depth := 0
	for !s.eof() {
		c := s.peek()
		if c == '\'' || c == '"' || c == '`' {
			s.skipString(c)
			continue
		}
		if c == '/' && s.at(1) == '/' {
			for !s.eof() && s.peek() != '\n' {
				s.pos++
			}
			continue
		}
		if c == '/' && s.at(1) == '*' {
			s.pos += 2
			for !s.eof() {
				if s.peek() == '*' && s.at(1) == '/' {
					s.pos += 2
					break
				}
				s.pos++
			}
			continue
		}
		if c == '{' {
			depth++
		} else if c == '}' {
			depth--
			if depth == 0 {
				s.pos++
				return
			}
		}
		s.pos++
	}
}

func (s *scanner) skipTo(ws byte) {
	for !s.eof() {
		c := s.peek()
		if c == '\'' || c == '"' || c == '`' {
			s.skipString(c)
			continue
		}
		if c == '/' && s.at(1) == '/' {
			for !s.eof() && s.peek() != '\n' {
				s.pos++
			}
			continue
		}
		if c == '/' && s.at(1) == '*' {
			s.pos += 2
			for !s.eof() {
				if s.peek() == '*' && s.at(1) == '/' {
					s.pos += 2
					break
				}
				s.pos++
			}
			continue
		}
		if c == ws {
			return
		}
		s.pos++
	}
}

// parseJS extracts the import statements, re-exports and export declarations of
// a javascript/typescript file.
func parseJS(src string) *jsParsed {
	p := &jsParsed{}
	sc := &scanner{src: src}
	for !sc.eof() {
		sc.skipWS()
		if sc.eof() {
			break
		}
		c := sc.peek()
		switch {
		case c == '\'' || c == '"' || c == '`':
			sc.skipString(c)
		case c == '/':
			if sc.at(1) == '/' {
				for !sc.eof() && sc.peek() != '\n' {
					sc.pos++
				}
			} else if sc.at(1) == '*' {
				sc.pos += 2
				for !sc.eof() {
					if sc.peek() == '*' && sc.at(1) == '/' {
						sc.pos += 2
						break
					}
					sc.pos++
				}
			} else if sc.regexAllowed() {
				sc.skipRegex()
			} else {
				sc.pos++
			}
		case isIdentStart(c):
			word := sc.readIdent()
			switch word {
			case "import":
				parseImport(sc, p)
			case "export":
				parseExport(sc, p)
			case "require":
				save := sc.pos
				sc.skipWS()
				if sc.peek() == '(' {
					sc.pos++
					sc.skipWS()
					if spec, ok := sc.readString(); ok {
						p.Imports = append(p.Imports, spec)
					}
				} else {
					sc.pos = save
				}
			}
		default:
			sc.pos++
		}
	}
	return p
}

func parseImport(sc *scanner, p *jsParsed) {
	sc.skipWS()
	if sc.peek() == '(' {
		// dynamic import
		sc.pos++
		sc.skipWS()
		if spec, ok := sc.readString(); ok {
			p.Imports = append(p.Imports, spec)
		}
		return
	}
	if q := sc.peek(); q == '\'' || q == '"' {
		if spec, ok := sc.readString(); ok {
			p.Imports = append(p.Imports, spec)
		}
		return
	}
	// import clause
	for {
		sc.skipWS()
		w := ""
		if isIdentStart(sc.peek()) {
			w = sc.readIdent()
		}
		if w == "type" || w == "typeof" || w == "defer" {
			sc.skipWS()
			if q := sc.peek(); q == '\'' || q == '"' {
				if spec, ok := sc.readString(); ok {
					p.Imports = append(p.Imports, spec)
				}
				return
			}
			continue
		}
		if w == "" {
			// not a valid clause, give up
			return
		}
		if w == "from" {
			sc.skipWS()
			if spec, ok := sc.readString(); ok {
				p.Imports = append(p.Imports, spec)
			}
			return
		}
		// default binding
		sc.skipWS()
		if sc.peek() == ',' {
			sc.pos++
			continue
		}
		if sc.peek() == '{' {
			sc.skipBlock()
			continue
		}
		if sc.peek() == '*' {
			// namespace import: * as ns
			sc.pos++
			sc.skipWS()
			if isIdentStart(sc.peek()) {
				w2 := sc.readIdent()
				_ = w2
			}
			continue
		}
		if sc.peek() == '=' {
			// import x = require('...')
			sc.pos++
			sc.skipWS()
			if isIdentStart(sc.peek()) {
				w2 := sc.readIdent()
				if w2 == "require" {
					sc.skipWS()
					if sc.peek() == '(' {
						sc.pos++
						sc.skipWS()
						if spec, ok := sc.readString(); ok {
							p.Imports = append(p.Imports, spec)
						}
						return
					}
				}
			}
			continue
		}
		// statement is not an import declaration
		return
	}
}

func parseExport(sc *scanner, p *jsParsed) {
	sc.skipWS()
	start := sc.pos
	spec := ""
	symbols := []string{}
	star := false
	if isIdentStart(sc.peek()) {
		w := sc.readIdent()
		switch w {
		case "type":
			sc.skipWS()
			if sc.peek() == '{' {
				sc.skipBlock()
				sc.skipWS()
				if isIdentStart(sc.peek()) {
					w2 := sc.readIdent()
					if w2 == "from" {
						sc.skipWS()
						if s, ok := sc.readString(); ok {
							spec = s
						}
					}
				}
				p.Exports = append(p.Exports, jsExport{Symbols: []string{}, Specifier: spec, Star: star})
				return
			}
			// export type X = ...
			sc.skipWS()
			if isIdentStart(sc.peek()) {
				name := sc.readIdent()
				symbols = append(symbols, name)
			}
			p.Exports = append(p.Exports, jsExport{Symbols: symbols, Specifier: "", Star: false})
			return
		case "default":
			symbols = append(symbols, "default")
			p.Exports = append(p.Exports, jsExport{Symbols: symbols, Specifier: "", Star: false})
			return
		case "async":
			sc.skipWS()
			if isIdentStart(sc.peek()) {
				w2 := sc.readIdent()
				if w2 == "function" {
					sc.skipWS()
					if sc.peek() == '*' {
						sc.pos++
					}
					sc.skipWS()
					if isIdentStart(sc.peek()) {
						symbols = append(symbols, sc.readIdent())
					}
					p.Exports = append(p.Exports, jsExport{Symbols: symbols, Specifier: "", Star: false})
					return
				}
			}
			symbols = append(symbols, w)
			p.Exports = append(p.Exports, jsExport{Symbols: symbols, Specifier: "", Star: false})
			return
		case "const", "let", "var", "function", "class", "enum", "interface", "abstract":
			sc.skipWS()
			if sc.peek() == '*' {
				sc.pos++
				sc.skipWS()
			}
			if isIdentStart(sc.peek()) {
				name := sc.readIdent()
				symbols = append(symbols, name)
				if w == "const" || w == "let" || w == "var" {
					// possibly multiple declarators
					for {
						save := sc.pos
						sc.skipWS()
						if sc.peek() != ',' {
							sc.pos = save
							break
						}
						sc.pos++
						sc.skipWS()
						if isIdentStart(sc.peek()) {
							symbols = append(symbols, sc.readIdent())
						} else {
							sc.pos = save
							break
						}
					}
				}
			}
			p.Exports = append(p.Exports, jsExport{Symbols: symbols, Specifier: "", Star: false})
			return
		}
	}
	if sc.peek() == '*' {
		sc.pos++
		star = true
		sc.skipWS()
		if isIdentStart(sc.peek()) {
			w := sc.readIdent()
			if w == "as" {
				sc.skipWS()
				if isIdentStart(sc.peek()) {
					name := sc.readIdent()
					symbols = append(symbols, name)
					star = false
				}
			}
		}
		sc.skipWS()
		if isIdentStart(sc.peek()) {
			w := sc.readIdent()
			if w == "from" {
				sc.skipWS()
				if s, ok := sc.readString(); ok {
					spec = s
				}
			}
		}
		p.Exports = append(p.Exports, jsExport{Symbols: symbols, Specifier: spec, Star: star})
		return
	}
	if sc.peek() == '{' {
		sc.skipBlock()
		sc.skipWS()
		if isIdentStart(sc.peek()) {
			w := sc.readIdent()
			if w == "from" {
				sc.skipWS()
				if s, ok := sc.readString(); ok {
					spec = s
				}
			}
		}
		// extract the exported names from the block
		blk := sc.src[start:sc.pos]
		symbols = extractExportNames(blk)
		p.Exports = append(p.Exports, jsExport{Symbols: symbols, Specifier: spec, Star: star})
		return
	}
	if sc.peek() == '=' {
		// export = require('...')
		sc.pos++
		sc.skipWS()
		if isIdentStart(sc.peek()) {
			w := sc.readIdent()
			if w == "require" {
				sc.skipWS()
				if sc.peek() == '(' {
					sc.pos++
					sc.skipWS()
					if s, ok := sc.readString(); ok {
						p.Imports = append(p.Imports, s)
					}
				}
			}
		}
		return
	}
	sc.pos = start
}

// extractExportNames pulls the exported identifiers out of `{ a, b as c, default as d }`
func extractExportNames(blk string) []string {
	inner := strings.TrimSuffix(strings.TrimPrefix(strings.TrimSpace(blk), "{"), "}")
	out := []string{}
	parts := splitTopLevel(inner, ',')
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		fields := splitTopLevel(part, ' ')
		last := fields[len(fields)-1]
		last = strings.TrimSpace(last)
		if last == "" || last == "," {
			continue
		}
		if last == "type" && len(fields) > 1 {
			last = strings.TrimSpace(fields[len(fields)-2])
		}
		out = append(out, last)
	}
	return out
}

func splitTopLevel(s string, sep byte) []string {
	var out []string
	depth := 0
	cur := strings.Builder{}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '{' || c == '[' || c == '(' {
			depth++
		} else if c == '}' || c == ']' || c == ')' {
			depth--
		}
		if c == sep && depth == 0 {
			out = append(out, cur.String())
			cur.Reset()
			continue
		}
		cur.WriteByte(c)
	}
	out = append(out, cur.String())
	return out
}

// resolveJS resolves a module specifier relative to the importing file
func resolveJS(spec, fromFile string, resolver *Resolver) (string, bool, error) {
	if spec == "" {
		return "", false, errImportEmpty
	}
	if len(spec) == 1 {
		return "", false, errInvalidImportPath(spec)
	}
	if strings.HasPrefix(spec, "./") || strings.HasPrefix(spec, "../") || spec == ".." {
		p := filepath.Join(filepath.Dir(fromFile), spec)
		return resolver.resolveJSPath(p)
	}
	// bare specifier: try workspaces
	if wp := resolver.resolveWorkspace(spec); wp != "" {
		return resolver.resolveJSPath(wp)
	}
	return "", false, nil
}
