package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

var errImportEmpty = errors.New("import path cannot be empty")

func errInvalidImportPath(p string) error {
	return fmt.Errorf("invalid import path %s", p)
}

func errRelativeNotFound(spec string) error {
	return fmt.Errorf("could not perform relative import for '%s' because the file or dir was not found", spec)
}

type workspace struct {
	name string
	dir  string
}

type Resolver struct {
	root       string // project root (empty when unknown)
	workspaces []workspace
	tsconfig   *tsconfigPaths
	lang       string
}

type tsconfigPaths struct {
	dir    string
	paths  map[string][]string
}

func (r *Resolver) resolveJSPath(p string) (string, bool, error) {
	st, err := os.Stat(p)
	if err == nil && st.IsDir() {
		for _, ext := range jsExts {
			cand := filepath.Join(p, "index"+ext)
			if fileExists(cand) {
				return cand, true, nil
			}
		}
		return "", false, errRelativeNotFound("")
	}
	base := strings.TrimSuffix(p, filepath.Ext(p))
	for _, ext := range jsExts {
		cand := base + ext
		if fileExists(cand) {
			return cand, true, nil
		}
	}
	return "", false, errRelativeNotFound("")
}

func fileExists(p string) bool {
	st, err := os.Stat(p)
	return err == nil && !st.IsDir()
}

// resolveWorkspace looks for a bare specifier matching one of the package.json
// workspaces of the project.
func (r *Resolver) resolveWorkspace(spec string) string {
	if r.root == "" {
		return ""
	}
	for _, w := range r.workspaces {
		if spec == w.name {
			return w.dir
		}
		prefix := w.name + "/"
		if strings.HasPrefix(spec, prefix) {
			return filepath.Join(w.dir, strings.TrimPrefix(spec, prefix))
		}
	}
	return ""
}

// loadWorkspaces reads the root package.json workspaces
func loadWorkspaces(root string) []workspace {
	out := []workspace{}
	pj := filepath.Join(root, "package.json")
	data, err := os.ReadFile(pj)
	if err != nil {
		return out
	}
	var pkg struct {
		Name       string   `json:"name"`
		Workspaces []string `json:"workspaces"`
	}
	if err := json.Unmarshal(data, &pkg); err != nil {
		return out
	}
	for _, w := range pkg.Workspaces {
		ws := filepath.Join(root, w)
		entries, err := os.ReadDir(ws)
		if err != nil {
			// maybe the workspace is a direct directory
			if fileExists(filepath.Join(ws, "package.json")) {
				name := readPackageName(ws)
				out = append(out, workspace{name: name, dir: ws})
			}
			continue
		}
		for _, e := range entries {
			if !e.IsDir() {
				continue
			}
			dir := filepath.Join(ws, e.Name())
			name := readPackageName(dir)
			if name == "" {
				continue
			}
			out = append(out, workspace{name: name, dir: dir})
		}
	}
	return out
}

func readPackageName(dir string) string {
	data, err := os.ReadFile(filepath.Join(dir, "package.json"))
	if err != nil {
		return ""
	}
	var pkg struct {
		Name string `json:"name"`
	}
	if err := json.Unmarshal(data, &pkg); err != nil {
		return ""
	}
	return pkg.Name
}

// loadTsconfig walks up from the given directory looking for a tsconfig.json or
// jsconfig.json and extracts the "paths" option.
func loadTsconfig(dir string) *tsconfigPaths {
	cur := dir
	for i := 0; i < 64; i++ {
		for _, name := range []string{"tsconfig.json", "jsconfig.json"} {
			p := filepath.Join(cur, name)
			data, err := os.ReadFile(p)
			if err != nil {
				continue
			}
			var cfg struct {
				CompilerOptions struct {
					Paths map[string][]string `json:"paths"`
				} `json:"compilerOptions"`
			}
			if err := json.Unmarshal(data, &cfg); err != nil {
				return nil
			}
			if len(cfg.CompilerOptions.Paths) == 0 {
				return nil
			}
			return &tsconfigPaths{dir: cur, paths: cfg.CompilerOptions.Paths}
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			break
		}
		cur = parent
	}
	return nil
}

// resolveTsconfig resolves a bare specifier through tsconfig paths
func (r *Resolver) resolveTsconfig(spec string) (string, bool) {
	if r.tsconfig == nil {
		return "", false
	}
	// exact match first
	if targets, ok := r.tsconfig.paths[spec]; ok {
		for _, t := range targets {
			p := t
			if !filepath.IsAbs(p) {
				p = filepath.Join(r.tsconfig.dir, p)
			}
			if fileExists(p) {
				return p, true
			}
		}
	}
	// pattern match
	for pat, targets := range r.tsconfig.paths {
		if !strings.Contains(pat, "*") {
			continue
		}
		pre := pat[:strings.Index(pat, "*")]
		suf := pat[strings.Index(pat, "*")+1:]
		if !strings.HasPrefix(spec, pre) || !strings.HasSuffix(spec, suf) {
			continue
		}
		mid := spec[len(pre) : len(spec)-len(suf)]
		for _, t := range targets {
			p := strings.Replace(t, "*", mid, 1)
			if !filepath.IsAbs(p) {
				p = filepath.Join(r.tsconfig.dir, p)
			}
			if fileExists(p) {
				return p, true
			}
		}
	}
	return "", false
}
