	if targets, ok := r.tsconfig.paths[spec]; ok {
		for _, t := range targets {
			p := t
			if !filepath.IsAbs(p) {
				p = filepath.Join(r.tsconfig.dir, p)
			}
			if fileExists(p) {
				return p, true
			}
		}
	}
	// pattern match
	for pat, targets := range r.tsconfig.paths {
		if !strings.Contains(pat, "*") {
			continue
		}
		pre := pat[:strings.Index(pat, "*")]
		suf := pat[strings.Index(pat, "*")+1:]
		if !strings.HasPrefix(spec, pre) || !strings.HasSuffix(spec, suf) {
			continue
		}
		mid := spec[len(pre) : len(spec)-len(suf)]
		for _, t := range targets {
			p := strings.Replace(t, "*", mid, 1)
			if !filepath.IsAbs(p) {
				p = filepath.Join(r.tsconfig.dir, p)
			}
			if fileExists(p) {
				return p, true
			}
		}
	}
