{"command": "cd /workspace && cat > graph.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
)

// Language detection and per file parsing results

type Language int

const (
	LangUnknown Language = iota
	LangJS
	LangPython
	LangGo
	LangRust
)

func langFor(path string) Language {
	switch strings.ToLower(filepath.Ext(path)) {
	case ".js", ".jsx", ".ts", ".tsx", ".mjs", ".cjs":
		return LangJS
	case ".py":
		return LangPython
	case ".go":
		return LangGo
	case ".rs":
		return LangRust
	}
	return LangUnknown
}

type FileNode struct {
	Path     string
	Loc      int
	Group    string
	deps     []string
	depSeen  map[string]bool
	Errors   []string
	errSeen  map[string]bool
	// language specific state
	exports    *orderedSymbols
	exportDone bool
	rustMods   map[string]string
}

type orderedSymbols struct {
	keys []string
	vals map[string]string
}

func newOrderedSymbols() *orderedSymbols {
	return &orderedSymbols{vals: map[string]string{}}
}

func (o *orderedSymbols) Set(k, v string) {
	if _, ok := o.vals[k]; !ok {
		o.keys = append(o.keys, k)
	}
	o.vals[k] = v
}

func (o *orderedSymbols) Get(k string) (string, bool) {
	v, ok := o.vals[k]
	return v, ok
}

type Graph struct {
	Nodes map[string]*FileNode
	order []string
	mu    sync.Mutex
	root  string
	lang  Language
	cfg   *Config
	// state used by the resolvers
	res *Resolver
}

func (g *Graph) list() []*FileNode {
	out := make([]*FileNode, 0, len(g.order))
	for _, p := range g.order {
		out = append(out, g.Nodes[p])
	}
	return out
}

func (g *Graph) get(path string) *FileNode { return g.Nodes[path] }

func (g *Graph) add(path string) *FileNode {
	if n, ok := g.Nodes[path]; ok {
		return n
	}
	n := &FileNode{Path: path, depSeen: map[string]bool{}, errSeen: map[string]bool{}}
	g.Nodes[path] = n
	g.order = append(g.order, path)
	return n
}

func (n *FileNode) addDep(p string) {
	if n.depSeen[p] {
		return
	}
	n.depSeen[p] = true
	n.deps = append(n.deps, p)
}

func (n *FileNode) addError(msg string) {
	if n.errSeen[msg] {
		return
	}
	n.errSeen[msg] = true
	n.Errors = append(n.Errors, msg)
}

// rootDir determines the project root for a file based on the language manifest
func rootDirFor(path string, lang Language) (string, string, bool) {
	dir := filepath.Dir(path)
	manifest := ""
	switch lang {
	case LangJS:
		manifest = "package.json"
	case LangPython:
		manifest = "pyproject.toml"
	case LangGo:
		manifest = "go.mod"
	case LangRust:
		manifest = "Cargo.toml"
	default:
		return "", "", false
	}
	cur := dir
	for i := 0; i < 128; i++ {
		if fileExists(filepath.Join(cur, manifest)) {
			return cur, manifest, true
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			break
		}
		cur = parent
	}
	return "", "", false
}

func groupFor(path string, lang Language, root string) string {
	switch lang {
	case LangJS:
		return readPackageName(root)
	case LangRust:
		return cargoPackageName(root)
	case LangGo:
		return goPackageName(path)
	case LangPython:
		return ""
	}
	return ""
}

func goPackageName(path string) string {
	// the package clause of the go file
	data, err := os.ReadFile(path)
	if err != nil {
		return ""
	}
	for _, line := range strings.Split(string(data), "\n") {
		l := strings.TrimSpace(line)
		l = stripGoComment(l)
		if strings.HasPrefix(l, "package ") {
			return strings.TrimSpace(strings.TrimPrefix(l, "package "))
		}
	}
	return ""
}

func stripGoComment(l string) string {
	if i := strings.Index(l, "//"); i >= 0 {
		return strings.TrimSpace(l[:i])
	}
	return l
}

func cargoPackageName(root string) string {
	data, err := os.ReadFile(filepath.Join(root, "Cargo.toml"))
	if err != nil {
		return ""
	}
	section := ""
	for _, line := range strings.Split(string(data), "\n") {
		l := strings.TrimSpace(line)
		if strings.HasPrefix(l, "[") && strings.HasSuffix(l, "]") {
			section = strings.TrimSpace(l[1 : len(l)-1])
			continue
		}
		if section == "package" {
			if strings.HasPrefix(l, "name") {
				i := strings.Index(l, "=")
				if i < 0 {
					continue
			}
				v := strings.TrimSpace(l[i+1:])
				v = strings.Trim(v, "\"'")
				return v
			}
		}
	}
	return ""
}

// NewGraph builds the dependency graph starting from the given entrypoints.
// The callback is invoked every time the progress bar should advance.
func NewGraph(entrypoints []string, cfg *Config, root string, onProgress func(total int)) (*Graph, error) {
	langs := map[Language]bool{}
	for _, e := range entrypoints {
		langs[langFor(e)] = true
	}
	if len(langs) == 0 {
		return nil, fmt.Errorf("none of the provided files belong to the a supported language")
	}
	if len(langs) > 1 {
		return nil, fmt.Errorf("files of different languages were provided")
	}
	var lang Language
	for l := range langs {
		lang = l
	}
	g := &Graph{Nodes: map[string]*FileNode{}, cfg: cfg, lang: lang}
	if lang == LangGo {
		if _, _, ok := rootDirFor(entrypoints[0], lang); !ok {
			return nil, fmt.Errorf("no go.mod file found in any parent directory of %s", entrypoints[0])
		}
	}
	if lang == LangRust {
		if _, _, ok := rootDirFor(entrypoints[0], lang); !ok {
			// the rust parser needs a cargo workspace
			_ = g
		}
	}
	g.root = root
	g.res = &Resolver{root: root, lang: "js"}
	if root != "" && lang == LangJS {
		g.res.workspaces = loadWorkspaces(root)
	}
	queue := append([]string{}, entrypoints...)
	seen := map[string]bool{}
	for _, e := range entrypoints {
		seen[e] = true
		g.add(e)
	}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		node := g.Nodes[cur]
		deps, err := g.parseNode(node)
		if err != nil {
			node.addError(err.Error())
		}
		if onProgress != nil {
			onProgress(len(g.order))
		}
		for _, d := range deps {
			if !seen[d] {
				seen[d] = true
				g.add(d)
				queue = append(queue, d)
			}
		}
	}
	return g, nil
}

// parseNode parses a file and returns the resolved dependencies
func (g *Graph) parseNode(node *FileNode) ([]string, error) {
	data, err := os.ReadFile(node.Path)
	if err != nil {
		return nil, err
	}
	node.Loc = strings.Count(string(data), "\n")
	node.Group = groupFor(node.Path, g.lang, g.root)
	switch g.lang {
	case LangJS:
		return g.parseJSNode(node, string(data))
	case LangPython:
		return g.parsePyNode(node, string(data))
	case LangGo:
		return g.parseGoNode(node, string(data))
	case LangRust:
		return g.parseRustNode(node, string(data))
	}
	return nil, fmt.Errorf("none of the provided files belong to the a supported language")
}

// relativeTo returns the path of `p` relative to the project root.  When p is
// outside the root the result is the empty string, mirroring the original.
func relativeTo(root, p string) string {
	if root == "" {
		return ""
	}
	rel, err := filepath.Rel(root, p)
	if err != nil {
		return ""
	}
	return filepath.ToSlash(rel)
}

// exportMapOf computes, lazily, the export map of a javascript file
func (g *Graph) exportMapOf(path string, visiting map[string]bool) *orderedSymbols {
	node := g.get(path)
	if node == nil {
		return newOrderedSymbols()
	}
	if node.exportDone {
		return node.exports
	}
	if visiting[path] {
		return newOrderedSymbols()
	}
	visiting[path] = true
	defer func() { visiting[path] = false }()
	data, err := os.ReadFile(path)
	if err != nil {
		return newOrderedSymbols()
	}
	parsed := parseJS(string(data))
	om := newOrderedSymbols()
	for _, ex := range parsed.Exports {
		if ex.Specifier == "" {
			for _, s := range ex.Symbols {
				om.Set(s, path)
			}
			continue
		}
		target, ok, err := resolveJS(ex.Specifier, path, g.res)
		if err != nil || !ok {
			continue
		}
		if ex.Star {
			sub := g.exportMapOf(target, visiting)
			for _, k := range sub.keys {
				om.Set(k, target)
			}
			continue
		}
		for _, s := range ex.Symbols {
			om.Set(s, target)
		}
	}
	node.exports = om
	node.exportDone = true
	return om
}

// SortedDeps returns the dependencies sorted by their relative path
func (n *FileNode) SortedDeps(root string) []string {
	out := append([]string{}, n.deps...)
	sort.Slice(out, func(i, j int) bool {
		return relativeTo(root, out[i]) < relativeTo(root, out[j])
	})
	return out
}

// TreeNode is a node of the dependency tree rendered by the tree command
type TreeNode struct {
	Path     string
	Name     string
	Children []*TreeNode
}

// BuildTree expands the dependency graph into a tree, expanding each node once
// per branch (a diamond shows the node twice) and stopping at cycles.
func BuildTree(g *Graph, root string) *TreeNode {
	var walk func(path string, stack map[string]bool) *TreeNode
	walk = func(path string, stack map[string]bool) *TreeNode {
		node := g.get(path)
		if node == nil {
			return nil
		}
		t := &TreeNode{Path: path, Name: relativeTo(root, path)}
		if stack[path] {
			return t
		}
		stack[path] = true
		defer delete(stack, path)
		deps := node.SortedDeps(root)
		for _, d := range deps {
			if c := walk(d, stack); c != nil {
				t.Children = append(t.Children, c)
			}
		}
		return t
	}
	return walk(g.order[0], map[string]bool{})
}

// BuildForest builds trees for all the entrypoints of the graph
func BuildForest(g *Graph, root string, entrypoints []string) []*TreeNode {
	out := []*TreeNode{}
	for _, e := range entrypoints {
		out = append(out, BuildTree(g, root))
	}
	return out
}

// DetectCycles finds the circular dependencies of the graph
func DetectCycles(g *Graph, entrypoints []string, root string) [][]string {
	out := [][]string{}
	seen := map[string]bool{}
	var walk func(path string, pathList []string, stack map[string]bool)
	walk = func(path string, pathList []string, stack map[string]bool) {
		node := g.get(path)
		if node == nil {
			return
		}
		if stack[path] {
			// find the start of the cycle
			idx := -1
			for i, p := range pathList {
				if p == path {
					idx = i
					break
			}
			}
			if idx < 0 {
				return
			}
			cyc := append([]string{}, pathList[idx:]...)
			cyc = append(cyc, path)
			rel := make([]string, len(cyc))
			for i, p := range cyc {
				rel[i] = relativeTo(root, p)
			}
			key := strings.Join(rel, "->")
			if !seen[key] {
				seen[key] = true
				out = append(out, rel)
			}
			return
		}
		stack[path] = true
		pathList = append(pathList, path)
		for _, d := range node.SortedDeps(root) {
			walk(d, pathList, stack)
		}
		delete(stack, path)
	}
	for _, e := range entrypoints {
		walk(e, nil, map[string]bool{})
	}
	return out
}
