// ---------- Go ----------

type goImport struct {
	Alias string
	Path  string
}

func parseGo(src string) []goImport {
	out := []goImport{}
	lines := strings.Split(src, "\n")
	inBlock := false
	for _, line := range lines {
		l := strings.TrimSpace(line)
		l = stripGoComment(l)
		if l == "" {
			continue
		}
		if strings.HasPrefix(l, "import") {
			rest := strings.TrimSpace(strings.TrimPrefix(l, "import"))
			if strings.HasPrefix(rest, "(") {
				inBlock = true
				rest = strings.TrimSpace(rest[1:])
				if rest != "" {
					if a, p, ok := parseGoImportPart(rest); ok {
						out = append(out, goImport{Alias: a, Path: p})
					}
				}
				continue
			}
			if a, p, ok := parseGoImportPart(rest); ok {
				out = append(out, goImport{Alias: a, Path: p})
			}
			continue
		}
		if inBlock {
			if strings.HasPrefix(l, ")") {
				inBlock = false
				continue
			}
			if a, p, ok := parseGoImportPart(l); ok {
				out = append(out, goImport{Alias: a, Path: p})
			}
		}
	}
	return out
}

func parseGoImportPart(s string) (string, string, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return "", "", false
	}
	if i := strings.Index(s, "//"); i >= 0 {
		s = strings.TrimSpace(s[:i])
	}
	if !strings.HasPrefix(s, "\"") {
		// alias form:  alias "path"
		i := strings.Index(s, "\"")
		if i < 0 {
			return "", "", false
		}
		alias := strings.TrimSpace(s[:i])
		end := strings.LastIndex(s, "\"")
		if end <= i {
			return "", "", false
		}
		return alias, s[i+1 : end], true
	}
	end := strings.LastIndex(s, "\"")
	if end < 1 {
		return "", "", false
	}
	return "", s[1:end], true
}

func (g *Graph) parseGoNode(node *FileNode, src string) ([]string, error) {
	deps := []string{}
	root := g.root
	module := ""
	if root != "" {
		module = goModuleName(filepath.Join(root, "go.mod"))
	}
	pkgName := strings.TrimSuffix(filepath.Base(node.Path), ".go")
	_ = pkgName
	// collect used identifiers for symbol based resolution
	used := goUsedSymbols(src)
	for _, imp := range parseGo(src) {
		if module == "" || imp.Path == "" {
			continue
		}
		if !strings.HasPrefix(imp.Path, module+"/") && imp.Path != module {
			continue
		}
		rel := strings.TrimPrefix(imp.Path, module)
		rel = strings.TrimPrefix(rel, "/")
		dir := filepath.Join(root, rel)
		st, err := os.Stat(dir)
		if err != nil {
			node.addError(fmt.Sprintf("open %s: no such file or directory", dir))
			continue
		}
		if !st.IsDir() {
			node.addError(fmt.Sprintf("readdirent %s: not a directory", dir))
			continue
		}
		// determine the alias used to reference the package
		alias := imp.Alias
		if alias == "" {
			alias = filepath.Base(rel)
		}
		if alias == "_" || alias == "." {
			// blank/dot import: no symbol resolution
			if alias == "." {
				// match any used symbol
				entries, _ := os.ReadDir(dir)
				names := []string{}
				for _, e := range entries {
					if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
						continue
					}
					names = append(names, filepath.Join(dir, e.Name()))
				}
				for _, u := range used {
					for _, f := range names {
						if goDefinesSymbol(f, u) {
							deps = append(deps, f)
							break
						}
					}
				}
			}
			continue
		}
		entries, _ := os.ReadDir(dir)
		files := []string{}
		for _, e := range entries {
			if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
				continue
			}
			files = append(files, filepath.Join(dir, e.Name()))
		}
		for _, u := range used {
			if !strings.HasPrefix(u, alias+".") {
				continue
			}
			sym := strings.TrimPrefix(u, alias+".")
			for _, f := range files {
				if goDefinesSymbol(f, sym) {
					deps = append(deps, f)
				}
			}
		}
	}
	return deps, nil
}

func goModuleName(path string) string {
	data, err := os.ReadFile(path)
	if err != nil {
		return ""
	}
	for _, line := range strings.Split(string(data), "\n") {
		l := strings.TrimSpace(line)
		if strings.HasPrefix(l, "module ") {
			v := strings.TrimSpace(strings.TrimPrefix(l, "module "))
			if v == "" {
				continue
			}
			return v
		}
	}
	return ""
}

// goUsedSymbols returns the identifiers referenced with a package qualifier, and
// bare identifiers (for dot imports)
func goUsedSymbols(src string) []string {
	out := []string{}
	seen := map[string]bool{}
	i := 0
	n := len(src)
	for i < n {
		c := src[i]
		if c == '"' {
			// skip string
			i++
			for i < n && src[i] != '"' {
				if src[i] == '\\' {
					i++
				}
				i++
			}
			i++
			continue
		}
		if c == '`' {
			i++
			for i < n && src[i] != '`' {
				i++
			}
			i++
			continue
		}
		if c == '/' && i+1 < n {
			if src[i+1] == '/' {
				for i < n && src[i] != '\n' {
					i++
				}
				continue
			}
			if src[i+1] == '*' {
				i += 2
				for i+1 < n && !(src[i] == '*' && src[i+1] == '/') {
					i++
				}
				i += 2
				continue
			}
		}
		if isIdentStart(c) || (c >= '0' && c <= '9') {
			start := i
			for i < n && (isIdentChar(src[i])) {
				i++
			}
			word := src[start:i]
			if isGoKeyword(word) {
				continue
			}
			// look ahead for a dot
			j := i
			for j < n && (src[j] == ' ' || src[j] == '\t' || src[j] == '\n' || src[j] == '\r') {
				j++
			}
			if j < n && src[j] == '.' && j+1 < n && (isIdentStart(src[j+1])) {
				k := j + 1
				for k < n && isIdentChar(src[k]) {
					k++
				}
				q := src[start:k]
				if !seen[q] {
					seen[q] = true
					out = append(out, q)
				}
				i = k
				continue
			}
			if !seen[word] {
				seen[word] = true
				out = append(out, word)
			}
			continue
		}
		i++
	}
	return out
}

var goKeywords = map[string]bool{
	"break": true, "case": true, "chan": true, "const": true, "continue": true,
	"default": true, "defer": true, "else": true, "fallthrough": true, "for": true,
	"func": true, "go": true, "goto": true, "if": true, "import": true, "interface": true,
	"map": true, "package": true, "range": true, "return": true, "select": true,
	"struct": true, "switch": true, "type": true, "var": true,
}

func isGoKeyword(w string) bool { return goKeywords[w] }

// goDefinesSymbol reports whether the go file declares the given symbol
func goDefinesSymbol(path, sym string) bool {
	data, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	s := string(data)
	return strings.Contains(s, "func "+sym+"(") ||
		strings.Contains(s, "func ("+sym) ||
		strings.Contains(s, "type "+sym+" ") ||
		strings.Contains(s, "var "+sym+" ") ||
		strings.Contains(s, "var "+sym+"=") ||
		strings.Contains(s, "const "+sym+" ") ||
		strings.Contains(s, "const "+sym+"=") ||
		strings.Contains(s, " "+sym+" = ")
}

// ---------- Rust ----------

type rustFile struct {
	Mods []string
	Uses []string
}

func parseRust(src string) *rustFile {
	f := &rustFile{}
	lines := strings.Split(src, "\n")
	for _, line := range lines {
		l := strings.TrimSpace(line)
		if i := strings.Index(l, "//"); i >= 0 {
			l = strings.TrimSpace(l[:i])
		}
		if l == "" {
			continue
		}
		if strings.HasPrefix(l, "mod ") {
			rest := strings.TrimSpace(strings.TrimPrefix(l, "mod "))
			rest = strings.TrimSuffix(rest, ";")
			rest = strings.TrimSpace(rest)
			if rest == "" || strings.Contains(rest, "{") {
				continue
			}
			if strings.Contains(rest, "::") {
				continue
			}
			f.Mods = append(f.Mods, rest)
			continue
		}
		if strings.HasPrefix(l, "use ") {
			rest := strings.TrimSpace(strings.TrimPrefix(l, "use "))
			rest = strings.TrimSuffix(rest, ";")
			rest = strings.TrimSpace(rest)
			if rest == "" {
				continue
			}
			f.Uses = append(f.Uses, rest)
		}
	}
	return f
}

type rustModNode struct {
	name     string
	file     string
	children map[string]*rustModNode
	order    []string
}

func (m *rustModNode) add(name, file string) *rustModNode {
	if m.children == nil {
		m.children = map[string]*rustModNode{}
	}
	if _, ok := m.children[name]; !ok {
		m.order = append(m.order, name)
	}
	n := &rustModNode{name: name, file: file}
	m.children[name] = n
	return n
}
