			}
			if a, p, ok := parseGoImportPart(rest); ok {
				out = append(out, goImport{Alias: a, Path: p})
			}
			continue
		}
		if inBlock {
			if strings.HasPrefix(l, ")") {
				inBlock = false
				continue
			}
			if a, p, ok := parseGoImportPart(l); ok {
				out = append(out, goImport{Alias: a, Path: p})
			}
