func parseGoImportPart(s string) (string, string, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return "", "", false
	}
	if i := strings.Index(s, "//"); i >= 0 {
		s = strings.TrimSpace(s[:i])
	}
	if !strings.HasPrefix(s, "\"") {
		// alias form:  alias "path"
		i := strings.Index(s, "\"")
		if i < 0 {
			return "", "", false
		}
		alias := strings.TrimSpace(s[:i])
		end := strings.LastIndex(s, "\"")
		if end <= i {
			return "", "", false
		}
		return alias, s[i+1 : end], true
	}
	end := strings.LastIndex(s, "\"")
	if end < 1 {
		return "", "", false
	}
	return "", s[1:end], true
}

