	used := goUsedSymbols(src)
	for _, imp := range parseGo(src) {
		if module == "" || imp.Path == "" {
			continue
		}
		if !strings.HasPrefix(imp.Path, module+"/") && imp.Path != module {
			continue
		}
		rel := strings.TrimPrefix(imp.Path, module)
		rel = strings.TrimPrefix(rel, "/")
		dir := filepath.Join(root, rel)
		st, err := os.Stat(dir)
		if err != nil {
