		if !st.IsDir() {
			node.addError(fmt.Sprintf("readdirent %s: not a directory", dir))
			continue
		}
		// determine the alias used to reference the package
		alias := imp.Alias
		if alias == "" {
			alias = filepath.Base(rel)
		}
		if alias == "_" || alias == "." {
			// blank/dot import: no symbol resolution
			if alias == "." {
				// match any used symbol
				entries, _ := os.ReadDir(dir)
				names := []string{}
				for _, e := range entries {
					if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
