// goUsedSymbols returns the identifiers referenced with a package qualifier, and
// bare identifiers (for dot imports)
func goUsedSymbols(src string) []string {
	out := []string{}
	seen := map[string]bool{}
	i := 0
	n := len(src)
	for i < n {
		c := src[i]
		if c == '"' {
			// skip string
			i++
			for i < n && src[i] != '"' {
				if src[i] == '\\' {
					i++
				}
				i++
			}
			i++
			continue
		}
		if c == '`' {
			i++
			for i < n && src[i] != '`' {
				i++
			}
			i++
			continue
		}
		if c == '/' && i+1 < n {
			if src[i+1] == '/' {
				for i < n && src[i] != '\n' {
					i++
				}
				continue
			}
			if src[i+1] == '*' {
				i += 2
				for i+1 < n && !(src[i] == '*' && src[i+1] == '/') {
					i++
				}
				i += 2
				continue
			}
		}
		if isIdentStart(c) || (c >= '0' && c <= '9') {
			start := i
			for i < n && (isIdentChar(src[i])) {
				i++
			}
			word := src[start:i]
			if isGoKeyword(word) {
				continue
			}
			// look ahead for a dot
			j := i
			for j < n && (src[j] == ' ' || src[j] == '\t' || src[j] == '\n' || src[j] == '\r') {
				j++
			}
			if j < n && src[j] == '.' && j+1 < n && (isIdentStart(src[j+1])) {
				k := j + 1
				for k < n && isIdentChar(src[k]) {
					k++
				}
				q := src[start:k]
				if !seen[q] {
					seen[q] = true
					out = append(out, q)
				}
				i = k
				continue
			}
			if !seen[word] {
				seen[word] = true
				out = append(out, word)
			}
			continue
		}
		i++
	}
	return out
}

var goKeywords = map[string]bool{
	"break": true, "case": true, "chan": true, "const": true, "continue": true,
	"default": true, "defer": true, "else": true, "fallthrough": true, "for": true,
	"func": true, "go": true, "goto": true, "if": true, "import": true, "interface": true,
	"map": true, "package": true, "range": true, "return": true, "select": true,
	"struct": true, "switch": true, "type": true, "var": true,
}

func isGoKeyword(w string) bool { return goKeywords[w] }

// goDefinesSymbol reports whether the go file declares the given symbol
func goDefinesSymbol(path, sym string) bool {
	data, err := os.ReadFile(path)
	if err != nil {
		return false
	}
	s := string(data)
	return strings.Contains(s, "func "+sym+"(") ||
		strings.Contains(s, "func ("+sym) ||
		strings.Contains(s, "type "+sym+" ") ||
		strings.Contains(s, "var "+sym+" ") ||
		strings.Contains(s, "var "+sym+"=") ||
		strings.Contains(s, "const "+sym+" ") ||
		strings.Contains(s, "const "+sym+"=") ||
		strings.Contains(s, " "+sym+" = ")
}

