func stripPyComment(l string) string {
	inS, inD := false, false
	for i := 0; i < len(l); i++ {
		c := l[i]
		if c == '#' && !inS && !inD {
			return l[:i]
		}
		if c == '\'' && !inD {
			inS = !inS
		} else if c == '"' && !inS {
			inD = !inD
		}
	}
	return l
