// resolvePyModule resolves a dotted module path starting from base
func resolvePyModule(base, mod string) string {
	cur := base
	parts := strings.Split(mod, ".")
	for i, part := range parts {
		if part == "" {
			continue
		}
		last := i == len(parts)-1
		cand := filepath.Join(cur, part)
		if last {
			if fileExists(cand + ".py") {
				return cand + ".py"
			}
			if dirExists(cand) {
				if f := filepath.Join(cand, "__init__.py"); fileExists(f) {
					return f
				}
