				if src[i] == '\\' {
					i++
				}
				i++
			}
			i++
			continue
		}
		if c == '`' {
			i++
			for i < n && src[i] != '`' {
				i++
			}
			i++
			continue
		}
		if c == '/' && i+1 < n {
			if src[i+1] == '/' {
				for i < n && src[i] != '\n' {
					i++
				}
				continue
			}
			if src[i+1] == '*' {
				i += 2
				for i+1 < n && !(src[i] == '*' && src[i+1] == '/') {
					i++
				}
				i += 2
				continue
			}
		}
		if isIdentStart(c) || (c >= '0' && c <= '9') {
			start := i
			for i < n && (isIdentChar(src[i])) {
				i++
			}
			word := src[start:i]
			if isGoKeyword(word) {
