// ---------- Rust ----------

type rustFile struct {
	Mods []string
	Uses []string
}

func parseRust(src string) *rustFile {
	f := &rustFile{}
	lines := strings.Split(src, "\n")
	for _, line := range lines {
		l := strings.TrimSpace(line)
		if i := strings.Index(l, "//"); i >= 0 {
			l = strings.TrimSpace(l[:i])
		}
		if l == "" {
			continue
		}
		if strings.HasPrefix(l, "mod ") {
			rest := strings.TrimSpace(strings.TrimPrefix(l, "mod "))
			rest = strings.TrimSuffix(rest, ";")
			rest = strings.TrimSpace(rest)
			if rest == "" || strings.Contains(rest, "{") {
				continue
			}
			if strings.Contains(rest, "::") {
				continue
			}
			f.Mods = append(f.Mods, rest)
			continue
		}
		if strings.HasPrefix(l, "use ") {
			rest := strings.TrimSpace(strings.TrimPrefix(l, "use "))
			rest = strings.TrimSuffix(rest, ";")
			rest = strings.TrimSpace(rest)
			if rest == "" {
				continue
			}
			f.Uses = append(f.Uses, rest)
		}
	}
	return f
}

type rustModNode struct {
	name     string
	file     string
	children map[string]*rustModNode
	order    []string
}

func (m *rustModNode) add(name, file string) *rustModNode {
	if m.children == nil {
		m.children = map[string]*rustModNode{}
	}
	if _, ok := m.children[name]; !ok {
		m.order = append(m.order, name)
	}
	n := &rustModNode{name: name, file: file}
	m.children[name] = n
	return n
}
