	if node.rustMods != nil {
		return node.rustMods, node.rustModOrder, nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return map[string]string{}, nil, nil
	}
	parsed := parseRust(string(data))
	mods := map[string]string{}
	order := []string{}
	dir := modDir(path)
	for _, m := range parsed.Mods {
		cand := filepath.Join(dir, m+".rs")
		if !fileExists(cand) {
			cand = filepath.Join(dir, m, "mod.rs")
		}
		if !fileExists(cand) {
			return nil, order, fmt.Errorf("could not find mod %q in path %q", m, dir)
		}
		mods[m] = cand
		order = append(order, m)
	}
	node.rustMods = mods
	node.rustModOrder = order
	return mods, order, nil
}

func (g *Graph) parseRustNode(node *FileNode, src string) ([]string, error) {
	deps := []string{}
	dir := filepath.Dir(node.Path)
	parsed := parseRust(src)
	// 1. resolve mods (dependency tree) using dirname(file)
	for _, m := range parsed.Mods {
		cand := filepath.Join(dir, m+".rs")
		if !fileExists(cand) {
			cand = filepath.Join(dir, m, "mod.rs")
		}
		if !fileExists(cand) {
			node.addError(fmt.Sprintf("could not find mod %s while looking in dir %s", m, dir))
			continue
		}
		deps = append(deps, cand)
	}
	// 2. resolve use statements
	if len(parsed.Uses) > 0 {
		cargoDir := findCargoDir(node.Path)
		if cargoDir == "" {
			// mirrors the nil pointer dereference of the original implementation
			var p *int
			_ = *p
		}
		crate := crateRoot(cargoDir)
		parent := g.rustParentOf(node.Path)
		for _, u := range parsed.Uses {
			path := u
			// strip the imported symbols list
			if i := strings.Index(path, "{"); i >= 0 {
				path = strings.TrimSpace(path[:i])
			}
			// strip alias
			if i := strings.Index(path, " as "); i >= 0 {
				path = strings.TrimSpace(path[:i])
			}
			if path == "" || strings.Contains(path, "*") {
				continue
			}
			segs := strings.Split(path, "::")
			anchor := node.Path
			createDep := false
			switch segs[0] {
			case "crate":
				if crate == "" {
					node.addError(fmt.Sprintf("error resolving use statement for name %s: main executable/library Rust file not found for cargo workspace in %s", lastName(u), cargoDir))
					continue
				}
				anchor = crate
				segs = segs[1:]
				createDep = true
			case "self":
				if crate == "" {
					node.addError(fmt.Sprintf("error resolving use statement for name %s: main executable/library Rust file not found for cargo workspace in %s", lastName(u), cargoDir))
					continue
				}
				anchor = node.Path
				segs = segs[1:]
				createDep = true
			case "super":
				if crate == "" {
					node.addError(fmt.Sprintf("error resolving use statement for name %s: main executable/library Rust file not found for cargo workspace in %s", lastName(u), cargoDir))
					continue
				}
				if parent == "" {
					node.addError(fmt.Sprintf("error resolving use statement for name %s: could not find mod chain in the projects mod tree", lastName(u)))
					continue
				}
				anchor = parent
				segs = segs[1:]
				createDep = true
			default:
				if crate == "" {
					node.addError(fmt.Sprintf("error resolving use statement for name %s: main executable/library Rust file not found for cargo workspace in %s", lastName(u), cargoDir))
					continue
				}
				anchor = node.Path
				createDep = false
			}
			if len(segs) <= 1 {
				continue
			}
			chain := segs[:len(segs)-1]
			cur := anchor
			ok := true
			for _, seg := range chain {
				mods, _, err := g.rustStrictMods(cur)
				if err != nil {
					node.addError(fmt.Sprintf("error resolving use statement for name %s: %v", lastName(u), err))
					ok = false
					break
				}
				f, found := mods[seg]
				if !found {
					if createDep {
						node.addError(fmt.Sprintf("error resolving use statement for name %s: could not find mod chain in the projects mod tree", lastName(u)))
					}
					ok = false
					break
				}
				cur = f
			}
			if !ok {
				continue
			}
			if createDep {
				deps = append(deps, cur)
			}
		}
	}
	return deps, nil
}

func lastName(u string) string {
	u = strings.TrimSpace(u)
	segs := strings.Split(u, "::")
	l := segs[len(segs)-1]
	if i := strings.Index(l, "{"); i >= 0 {
		l = strings.TrimSpace(l[:i])
	}
	if i := strings.Index(l, " as "); i >= 0 {
		l = strings.TrimSpace(l[:i])
	}
	return l
}

// rustParentOf finds the file that declares the given file as a mod
func (g *Graph) rustParentOf(path string) string {
	if g.rustParents == nil {
		g.rustParents = map[string]string{}
	}
	if p, ok := g.rustParents[path]; ok {
		return p
	}
	// walk up: the parent mod file is the one declaring this file
	dir := filepath.Dir(path)
	base := strings.TrimSuffix(filepath.Base(path), filepath.Ext(path))
	var candidates []string
	if filepath.Base(path) == "mod.rs" {
		candidates = append(candidates, filepath.Join(filepath.Dir(dir), strings.TrimSuffix(filepath.Base(dir), "")))
		// a dir mod: the parent is <dir>/../<dirbase>.rs or the crate root
		parentDir := filepath.Dir(dir)
		name := filepath.Base(dir)
		candidates = []string{filepath.Join(parentDir, name+".rs")}
	} else {
		candidates = []string{
			filepath.Join(dir, base+".rs"),
			filepath.Join(dir, base, "mod.rs"),
			filepath.Join(dir, "mod.rs"),
			filepath.Join(dir, "lib.rs"),
			filepath.Join(dir, "main.rs"),
		}
	}
	for _, c := range candidates {
		if !fileExists(c) {
			continue
		}
		data, err := os.ReadFile(c)
		if err != nil {
			continue
		}
		parsed := parseRust(string(data))
		for _, m := range parsed.Mods {
			cand := filepath.Join(filepath.Dir(c), m+".rs")
			if !fileExists(cand) {
				cand = filepath.Join(filepath.Dir(c), m, "mod.rs")
			}
			if cand == path {
				g.rustParents[path] = c
				return c
			}
		}
	}
	g.rustParents[path] = ""
	return ""
}
