	renders     int
	finished    bool
}

func NewProgressBar() *ProgressBar {
	return &ProgressBar{w: os.Stderr, total: -1, start: time.Now()}
}

func (b *ProgressBar) frame() string {
	elapsed := time.Since(b.start)
	idx := int(elapsed / (100 * time.Millisecond))
	return spinnerFrames[idx%len(spinnerFrames)]
