	sb.WriteString(" ")
	return sb.String()
}

func (b *ProgressBar) rateString() string {
	elapsed := time.Since(b.start)
	if elapsed <= 0 {
		return "(0 it/hr)"
	}
	rate := float64(b.current) / elapsed.Seconds()
	if rate < 1 {
		return fmt.Sprintf("(%.0f it/hr)", rate*3600)
	}
	return fmt.Sprintf("(%.0f it/s)", rate)
}

func (b *ProgressBar) SetTotal(n int) {
	b.total = n
	b.render()
}

func (b *ProgressBar) Increment() {
	b.current++
	b.render()
}

func (b *ProgressBar) SetDescription(d string) {
	b.description = d
	b.render()
}

func (b *ProgressBar) Finish() {
	if b.finished {
		return
	}
	b.description = "Finished loading"
	b.render()
	s := b.String()
	fmt.Fprint(b.w, "\r"+strings.Repeat(" ", b.lastWidth)+"\r\r"+s+"\n")
	b.finished = true
}
