package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const bannerText = "\n" +
	"      ____         _ __       _\n" +
	"     |  _ \\   ___ |  _ \\    _| |_  _ __  ___   ___\n" +
	"     | | | | / _ \\| |_) |  |_   _||  __|/ _ \\ / _ \\\n" +
	"     | |_| ||  __/| .__/     | |  | |  |  __/|  __/\n" +
	"     |____/  \\__| |_|        | \\__|_|   \\___| \\___|\n" +
	"\n"

func rootHelp() string {
	return bannerText +
		"Usage:\n" +
		"  dep-tree [command]\n" +
		"\n" +
		"Examples:\n" +
		"$ dep-tree src/index.ts\n" +
		"$ dep-tree entropy src/index.ts\n" +
		"$ dep-tree tree package/main.py --unwrap-exports\n" +
		"$ dep-tree check\n" +
		"\n" +
		"Visualize your dependencies graphically\n" +
		"  entropy     (default) Renders a 3d force-directed graph in the browser\n" +
		"  tree        Render the dependency tree starting from the provided entrypoint\n" +
		"\n" +
		"Check your dependencies against your own rules\n" +
		"  check       Checks that the dependency rules defined in the configuration file are not broken\n" +
		"\n" +
		"Display what are the dependencies between two portions of code\n" +
		"  explain     Shows all the dependencies between two parts of the code\n" +
		"\n" +
		"Additional Commands:\n" +
		"  config      Generates a sample config in case that there's not already one present\n" +
		"  help        Help about any command\n" +
		"\n" +
		"Flags:\n" +
		"  -c, --config string                        path to dep-tree's config file. (default .dep-tree.yml)\n" +
		"      --unwrap-exports                       trace re-exported symbols to the file where they are declared. (default false)\n" +
		"      --js-tsconfig-paths                    follow the tsconfig.json paths while resolving imports. (default true)\n" +
		"      --js-workspaces                        take the workspaces attribute in the root package.json into account for resolving paths. (default true)\n" +
		"      --python-exclude-conditional-imports   exclude imports wrapped inside if or try statements. (default false)\n" +
		"      --only stringArray                     Files that do not match this glob pattern will be ignored. You can provide an arbitrary number of --only flags.\n" +
		"      --exclude stringArray                  Files that match this glob pattern will be ignored. You can provide an arbitrary number of --exclude flags.\n" +
		"  -h, --help                                 help for dep-tree\n" +
		"  -v, --version                              version for dep-tree\n" +
		"\n" +
		"Use \"dep-tree [command] --help\" for more information about a command.\n"
}

func main() {
	root := buildCommands()
	args := os.Args[1:]
	// Cobra style: no args prints the help of the root command
	if len(args) == 0 {
		fmt.Print(rootHelp())
		return
	}
	os.Exit(root.Execute(args))
}

func addPersistentFlags(c *Command) {
	c.String("config", "c", "path to dep-tree's config file.", ".dep-tree.yml")
	c.Bool("unwrap-exports", "", "trace re-exported symbols to the file where they are declared.", false)
	c.Bool("js-tsconfig-paths", "", "follow the tsconfig.json paths while resolving imports.", true)
	c.Bool("js-workspaces", "", "take the workspaces attribute in the root package.json into account for resolving paths.", true)
	c.Bool("python-exclude-conditional-imports", "", "exclude imports wrapped inside if or try statements.", false)
	c.StringArray("only", "", "Files that do not match this glob pattern will be ignored. You can provide an arbitrary number of --only flags.")
	c.StringArray("exclude", "", "Files that match this glob pattern will be ignored. You can provide an arbitrary number of --exclude flags.")
}

func buildCommands() *Command {
	root := &Command{
		Use:   "dep-tree",
		Short: "Visualize the entropy of a code base with a 3d force directed graph",
	}
	root.Long = ""
	root.Examples = ""
	addPersistentFlags(root)

	entropy := &Command{
		Use:   "entropy",
		Short: "(default) Renders a 3d force-directed graph in the browser",
	}
	entropy.String("render-path", "", "Sets the output path of the rendered html file", "")
	entropy.Bool("no-browser-open", "", "Disable the automatic browser open while rendering entropy", false)
	entropy.Bool("enable-gui", "", "Enables a GUI for changing rendering settings", false)
	entropy.Args = minimumNArgs(1)
	entropy.Run = runEntropy

	tree := &Command{
		Use:   "tree",
		Short: "Render the dependency tree starting from the provided entrypoint",
	}
	tree.Bool("json", "", "render the dependency tree in a machine readable json format", false)
	tree.Args = minimumNArgs(1)
	tree.Run = runTree

	check := &Command{
		Use:   "check",
		Short: "Checks that the dependency rules defined in the configuration file are not broken",
	}
	check.Args = exactArgs(0)
	check.Run = runCheck

	explain := &Command{
		Use:   "explain",
		Short: "Shows all the dependencies between two parts of the code",
	}
	explain.Bool("overlap-left", "l", "When there's an overlap between the files at the left and the right, keep the ones at the left", false)
	explain.Bool("overlap-right", "r", "When there's an overlap between the files at the left and the right, keep the ones at the right", false)
	explain.Args = exactArgs(2)
	explain.Run = runExplain

	config := &Command{
		Use:     "config",
		Short:   "Generates a sample config in case that there's not already one present",
		Aliases: []string{"init"},
	}
	config.Args = exactArgs(0)
	config.Run = runConfig

	help := &Command{
		Use:   "help [command]",
		Short: "Help about any command",
		Long:  "Help provides help for any command in the application.\nSimply type dep-tree help [path to command] for full details.",
	}
	help.Run = func(c *Command, args []string) error {
		if len(args) == 0 {
			root.printHelp()
			return nil
		}
		sub := root.findSub(args[0])
		if sub == nil {
			fmt.Print(rootHelp())
			return nil
		}
		sub.printHelp()
		return nil
	}

	root.AddCommand(entropy)
	root.AddCommand(tree)
	root.AddCommand(check)
	root.AddCommand(explain)
	root.AddCommand(config)
	root.AddCommand(help)
	root.Run = func(c *Command, args []string) error {
		return runEntropy(c, args)
	}
	return root
}

func minimumNArgs(n int) func(args []string) error {
	return func(args []string) error {
		if len(args) < n {
			return fmt.Errorf("requires at least %d arg(s), only received %d", n, len(args))
		}
		return nil
	}
}

func exactArgs(n int) func(args []string) error {
	return func(args []string) error {
		if len(args) != n {
			return fmt.Errorf("accepts %d arg(s), received %d", n, len(args))
		}
		return nil
	}
}

// selectEntrypoints expands the globs and filters the files
func selectEntrypoints(args []string, cfg *Config, c *Command) ([]string, error) {
	var files []string
	for _, a := range args {
		matches := Glob(a)
		if len(matches) == 0 {
			return nil, fmt.Errorf("%s does not match with any existing file", a)
		}
		for _, m := range matches {
			st, err := os.Stat(m)
			if err != nil || st.IsDir() {
				continue
			}
			files = append(files, m)
		}
	}
	if len(files) == 0 {
		return nil, fmt.Errorf("no valid files where provided")
	}
	abs := []string{}
	for _, f := range files {
