			return true
		}
	}
	for _, pat := range cfg.Exclude {
		if matchGlob(pat, path) {
			return true
		}
	}
	only := append([]string{}, c.arrayFlag("only")...)
	only = append(only, cfg.Only...)
	if len(only) > 0 {
		for _, pat := range only {
			if matchGlob(pat, path) {
				return false
			}
		}
		return true
	}
	return false
}

// treeJSON renders the tree in the machine readable format
func treeJSON(g *Graph, root string, entrypoints []string) (string, error) {
	var walk func(path string, stack map[string]bool) map[string]interface{}
	walk = func(path string, stack map[string]bool) map[string]interface{} {
		node := g.get(path)
		if node == nil {
			return nil
		}
		if stack[path] {
			return nil
		}
		stack[path] = true
		defer delete(stack, path)
		if len(node.deps) == 0 {
			return nil
		}
		out := map[string]interface{}{}
		deps := node.SortedDeps(root)
		for _, d := range deps {
			out[relativeTo(root, d)] = walk(d, stack)
		}
		return out
	}
	tree := map[string]interface{}{}
	for _, e := range entrypoints {
		if m := walk(e, map[string]bool{}); m != nil {
			for k, v := range m {
				tree[k] = v
			}
		} else {
			tree[relativeTo(root, e)] = nil
		}
	}
	cycles := DetectCycles(g, entrypoints, root)
	if cycles == nil {
		cycles = [][]string{}
	}
	errs := map[string][]string{}
	for _, n := range g.list() {
		if len(n.Errors) > 0 {
			errs[relativeTo(root, n.Path)] = n.Errors
		}
	}
	payload := map[string]interface{}{
		"tree":                 tree,
		"circularDependencies": cycles,
		"errors":               errs,
	}
	b, err := json.MarshalIndent(payload, "", "  ")
	if err != nil {
		return "", err
	}
	return string(b) + "\n", nil
}

func runTree(c *Command, args []string) error {
	cfg, cfgPath, err := LoadConfig(c.stringFlag("config"))
	if err != nil {
		return err
	}
	_ = cfgPath
	files, err := selectEntrypoints(args, cfg, c)
	if err != nil {
