	}
	if len(files) != 1 {
		return fmt.Errorf("this functionality requires that only 1 entrypoint is provided, but %d where passed. Consider providing a single entrypoint to your program", len(files))
	}
	if ignored(files[0], cfg, c) {
		b := NewProgressBar()
		b.SetTotal(1)
		b.Finish()
		return fmt.Errorf("selected entrypoint %s is explicitly ignored", files[0])
	}
	bar := NewProgressBar()
	bar.render()
	bar.render()
	total := 0
	g, err := NewGraph(files, cfg, "", func(t int) {
		_ = t
	})
	if err != nil {
		return err
	}
	// load with progress reporting
	bar2 := NewProgressBar()
	bar2.render()
	bar2.render()
	current := 0
	g2, err := loadWithProgress(files, cfg, bar2, &current)
	if err != nil {
		return err
