		if err != nil {
			return err
		}
		st, err2 := os.Stat(abs)
		if err2 != nil {
			return err2
		}
		if st.IsDir() {
			continue
		}
		if langFor(abs) == LangUnknown {
			return fmt.Errorf("none of the provided files belong to the a supported language")
		}
		files = append(files, abs)
	}
	if len(files) == 0 {
		return fmt.Errorf("none of the provided files belong to the a supported language")
	}
