	for _, f := range files {
		l.seen[f] = true
		l.g.add(f)
	}
	bar.SetTotal(len(files))
	// consume the queue but only count the entrypoints in the progress bar
	bar.current = 0
	for len(l.queue) > 0 {
		cur := l.queue[0]
		l.queue = l.queue[1:]
		node := l.g.Nodes[cur]
		deps, perr := l.g.parseNode(node)
		if perr != nil {
			node.addError(perr.Error())
		}
		for _, d := range deps {
			if l.seen[d] || ignored(d, cfg, c) {
				continue
			}
			l.seen[d] = true
			l.g.add(d)
			l.queue = append(l.queue, d)
		}
	}
	for i := 0; i < len(files); i++ {
		bar.current = i + 1
		if i == len(files)-1 {
			bar.render()
		} else {
			bar.render()
			bar.render()
		}
	}
	bar.Finish()
	return checkRules(cfg, l.g, files, c)
}
