// graphLoader loads the dependency graph reporting the progress the way the
// original binary does: two blank renders, two renders per loaded file (except
// the last one, which renders once) and two "finished" renders.
type graphLoader struct {
	g       *Graph
	bar     *ProgressBar
	cfg     *Config
	c       *Command
	queue   []string
	seen    map[string]bool
	loaded  int
	isFirst bool
}

func newLoader(files []string, cfg *Config, c *Command, bar *ProgressBar) *graphLoader {
	l := &graphLoader{bar: bar, cfg: cfg, c: c, queue: append([]string{}, files), seen: map[string]bool{}, isFirst: true}
	lang := langFor(files[0])
	root, _, _ := rootDirFor(files[0], lang)
	l.g = &Graph{Nodes: map[string]*FileNode{}, cfg: cfg, lang: lang, root: root}
	l.g.res = &Resolver{root: root, lang: "js"}
	if root != "" && lang == LangJS {
		l.g.res.workspaces = loadWorkspaces(root)
		l.g.res.tsconfig = loadTsconfig(filepath.Dir(files[0]))
	}
	if lang == LangRust {
		l.g.res.cargoDir = findCargoDir(files[0])
		l.g.res.crateRoot = crateRoot(l.g.res.cargoDir)
	}
	if lang == LangGo {
		l.g.res.root = root
	}
	for _, f := range files {
		l.seen[f] = true
		l.g.add(f)
	}
	return l
}

func (l *graphLoader) run() error {
	for len(l.queue) > 0 {
		cur := l.queue[0]
		l.queue = l.queue[1:]
		node := l.g.Nodes[cur]
		deps, err := l.g.parseNode(node)
		if err != nil {
			node.addError(err.Error())
		}
		for _, d := range deps {
			if l.seen[d] || ignored(d, l.cfg, l.c) {
				continue
			}
			l.seen[d] = true
			l.g.add(d)
			l.queue = append(l.queue, d)
		}
		l.loaded++
		l.bar.SetTotal(len(l.g.order))
		l.bar.current = l.loaded
		last := len(l.queue) == 0
		if last {
			l.bar.render()
		} else {
			l.bar.render()
			l.bar.render()
		}
	}
	return nil
}

func loadGraph(files []string, cfg *Config, c *Command) (*Graph, *ProgressBar, error) {
	bar := NewProgressBar()
	bar.render()
	bar.render()
	l := newLoader(files, cfg, c, bar)
	if err := l.run(); err != nil {
		return nil, bar, err
	}
	return l.g, bar, nil
}

func finishBar(bar *ProgressBar) {
	bar.Finish()
}

func runTree(c *Command, args []string) error {
	cfg, _, err := LoadConfig(c.stringFlag("config"))
	if err != nil {
		return err
	}
	files, err := selectEntrypoints(args, cfg, c)
	if err != nil {
		return err
	}
	if len(files) != 1 {
		return fmt.Errorf("this functionality requires that only 1 entrypoint is provided, but %d where passed. Consider providing a single entrypoint to your program", len(files))
	}
	if ignored(files[0], cfg, c) {
		b := NewProgressBar()
		b.render()
		b.SetTotal(len(files))
		b.Finish()
		return fmt.Errorf("selected entrypoint %s is explicitly ignored", files[0])
	}
	g, bar, err := loadGraph(files, cfg, c)
	if err != nil {
		return err
	}
	finishBar(bar)
	root := g.root
	out, err := treeJSON(g, root, files)
	if err != nil {
		return err
	}
