func runExplain(c *Command, args []string) error {
	cfg, _, err := LoadConfig(c.stringFlag("config"))
	if err != nil {
		return err
	}
	left, err := selectEntrypoints([]string{args[0]}, cfg, c)
	if err != nil {
		return err
	}
	right, err := selectEntrypoints([]string{args[1]}, cfg, c)
	if err != nil {
		return err
	}
	leftSet := map[string]bool{}
	for _, f := range left {
		leftSet[f] = true
	}
	rightSet := map[string]bool{}
	for _, f := range right {
		rightSet[f] = true
	}
	overlapLeft := c.boolFlag("overlap-left")
	overlapRight := c.boolFlag("overlap-right")
	leftFiles := []string{}
	rightFiles := []string{}
	for _, f := range left {
		if overlapLeft && rightSet[f] {
			leftFiles = append(leftFiles, f)
		} else if !overlapLeft || !rightSet[f] {
			leftFiles = append(leftFiles, f)
		}
	}
	for _, f := range right {
		if overlapLeft && leftSet[f] {
			continue
		}
		if overlapRight && leftSet[f] {
			rightFiles = append(rightFiles, f)
			continue
		}
		if !overlapRight || !leftSet[f] {
			rightFiles = append(rightFiles, f)
		}
	}
	_ = leftFiles
	// the files to load are the union of both sets
	all := map[string]bool{}
	for _, f := range left {
		all[f] = true
	}
	for _, f := range right {
		all[f] = true
	}
	var list []string
	for f := range all {
		list = append(list, f)
	}
	sort.Strings(list)
	g, bar, err := loadGraph(list, cfg, c)
	if err != nil {
		return err
	}
	finishBar(bar)
	root := g.root
	out := []string{}
	for _, f := range list {
		node := g.get(f)
		if node == nil {
			continue
		}
		isLeft := leftSet[f]
		if overlapLeft {
			isLeft = leftSet[f] && rightSet[f]
			if !isLeft {
				isLeft = leftSet[f]
			}
		}
		if overlapRight {
			isLeft = leftSet[f] && !rightSet[f]
		}
		if !isLeft {
			continue
		}
		for _, d := range node.SortedDeps(root) {
			var include bool
			switch {
			case overlapLeft:
				include = rightSet[d] && !leftSet[d]
			case overlapRight:
				include = rightSet[d]
			default:
				include = rightSet[d]
			}
			if include {
				out = append(out, fmt.Sprintf("%s -> %s\n", relativeTo(root, f), relativeTo(root, d)))
			}
		}
	}
	sort.Strings(out)
	for _, l := range out {
		fmt.Print(l)
	}
	return nil
}

