		// deny rules
		denyPats := []string{}
		for key, rules := range cfg.Check.Deny {
			if !matchGlob(key, n.Path) && !matchGlob(key, from) {
				continue
			}
			for _, r := range rules {
				if r.IsList {
					denyPats = append(denyPats, expandPatterns([]string{r.Plain}, aliases)...)
				} else {
					denyPats = append(denyPats, expandPatterns([]string{r.To}, aliases)...)
				}
			}
		}
		// allow rules
		allowPats := []string{}
		hasAllow := false
		for key, rules := range cfg.Check.Allow {
			if !matchGlob(key, n.Path) && !matchGlob(key, from) {
				continue
			}
			hasAllow = true
			for _, r := range rules {
				if r.IsList {
					allowPats = append(allowPats, expandPatterns(r.Plain, aliases)...)
					if r.Reason != "" {
						allowReasons[from] = r.Reason
					}
				} else {
					allowPats = append(allowPats, expandPatterns(r.To, aliases)...)
					if r.Reason != "" {
						allowReasons[from] = r.Reason
					}
				}
			}
		}
		for _, d := range n.deps {
			to := relativeTo(root, d)
			denied := false
			reason := ""
			for _, pat := range denyPats {
				if matchGlob(pat, d) || matchGlob(pat, to) {
					denied = true
					if reason == "" {
						reason = denyReasonOf(cfg, n.Path, from, d, to)
					}
					break
				}
			}
			if denied {
				addViolation(from, to, reason)
				continue
			}
			if hasAllow {
				ok := false
				for _, pat := range allowPats {
					if matchGlob(pat, d) || matchGlob(pat, to) {
						ok = true
						break
					}
				}
				if !ok {
					addViolation(from, to, allowReasons[from])
				}
			}
		}
	}
	if !cfg.Check.AllowCircularDependencies {
		cycles := DetectCycles(g, entrypoints, root)
		if len(cycles) > 0 {
			sb := strings.Builder{}
			sb.WriteString("\ndetected circular dependencies:")
			for _, cyc := range cycles {
				sb.WriteString("\n- " + strings.Join(cyc, " -> "))
			}
			sb.WriteString("\n")
			violations = append(violations, sb.String())
		}
	}
	if len(violations) > 0 {
		return fmt.Errorf("Check failed, the following dependencies are not allowed:\n%s\n", strings.Join(violations, "\n"))
	}
	return nil
}

var allowReasons = map[string]string{}

func denyReasonOf(cfg *Config, path, from, dep, to string) string {
	for key, rules := range cfg.Check.Deny {
		if !matchGlob(key, path) && !matchGlob(key, from) {
			continue
		}
		for _, r := range rules {
			pat := r.Plain
			if !r.IsList {
				pat = r.To
			}
			pat = expandPatterns([]string{pat}, cfg.Check.Aliases)[0]
			if matchGlob(pat, dep) || matchGlob(pat, to) {
				return r.Reason
			}
		}
	}
	return ""
}
