		rel := relativeTo(root, p)
		dirName := filepath.ToSlash(filepath.Dir(rel)) + "/"
		fileName := filepath.Base(rel)
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(fmt.Sprintf(`{"id":%d,"isEntrypoint":%v,"fileName":%s,"pathBuf":[`, idOf[p], len(entrypoints) == 1 && p == entrypoints[0], jsonStr(fileName)))
		for j, part := range strings.Split(p, "/") {
			if j > 0 {
				sb.WriteString(",")
			}
			sb.WriteString(jsonStr(part))
		}
		sb.WriteString("]")
		if node.Group != "" {
			sb.WriteString(`,"group":` + jsonStr(node.Group))
		}
		sb.WriteString(fmt.Sprintf(`,"dirName":%s,"loc":%d,"size":%d}`, jsonStr(dirName), node.Loc, nodeSize(node, nodeOrder)))
	}
	sb.WriteString(`],"links":[`)
	for i, l := range links {
		if i > 0 {
			sb.WriteString(",")
		}
