	return entropyHTML(strings.ReplaceAll(entropyTemplate, "__INLINE_DATA_PLACEHOLDER__", sb.String())), nil
}

func nodeSize(node *FileNode, order []string) int {
	max := 0
	for _, p := range order {
		n := g_node(p)
		if n != nil && n.Loc > max {
			max = n.Loc
		}
	}
	if max <= 0 {
		return 0
	}
	return node.Loc * 10 / max
}

func jsonStr(s string) string {
	b, _ := jsonMarshalString(s)
	return b
}

func isCyclicLink(g *Graph, from, to string, entrypoints []string, root string) bool {
	// a link is cyclic when it closes a cycle
	return false
}
